INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dogs-&-cats---best-friends-erising-sun', 'GAMEBOYADVANCE', 'Dogs & Cats - Best Friends (E)(Rising Sun)', '2004', 'Simulation', 'Magic Pockets', '1', 'Pet Care Simulation', 'Virtual pet simulation and social play.', 'Care for both puppies and kittens in one digital home.', 'A heartwarming pet simulation featuring diverse animals.', 'Dogs & Cats - Best Friends offers the best of both worlds. Manage the different needs of your pets, play mini-games together, and ensure they live in a happy, healthy environment on your GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dogz---fashion-esir-vg', 'GAMEBOYADVANCE', 'Dogz - Fashion (E)(Sir VG)', '2006', 'Simulation', 'MTO', '1', 'Fashion Simulation', 'Virtual pet simulation with a fashion twist.', 'Dress up your dog and win the prestigious fashion show.', 'A unique blend of pet care and fashion design.', 'Dogz - Fashion lets you style your digital pets with a wide array of outfits and accessories. Balance their care needs with their runway preparation to become the top pet stylist in the city.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dogz---fashion-urising-sun', 'GAMEBOYADVANCE', 'Dogz - Fashion (U)(Rising Sun)', '2006', 'Simulation', 'MTO', '1', 'Fashion Simulation', 'Virtual pet simulation with a fashion twist.', 'Dress up your dog and win the prestigious fashion show.', 'A unique blend of pet care and fashion design.', 'The US version of Dogz - Fashion offers a creative and colorful experience. Customize your dog''s look and participate in various fashion-themed mini-games to unlock new clothing and items.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dogz-erising-sun', 'GAMEBOYADVANCE', 'Dogz (E)(Rising Sun)', '2005', 'Simulation', 'MTO', '1', 'Pet Care Simulation', 'Virtual pet simulation.', 'Adopt, raise, and bond with a virtual puppy.', 'A portable version of the popular PC pet simulator.', 'Dogz for GBA lets you care for your own digital puppy. Feed, groom, and train your pet to perform tricks while keeping them happy and healthy in this relaxing handheld simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dogz-esir-vg', 'GAMEBOYADVANCE', 'Dogz (E)(Sir VG)', '2005', 'Simulation', 'MTO', '1', 'Pet Care Simulation', 'Virtual pet simulation.', 'Adopt, raise, and bond with a virtual puppy.', 'The European edition of the classic dog care game.', 'This version of Dogz offers a wide variety of breeds to choose from. Manage your puppy''s daily routine and unlock new toys and environments as your bond grows stronger.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dogz-esupplex', 'GAMEBOYADVANCE', 'Dogz (E)(sUppLeX)', '2005', 'Simulation', 'MTO', '1', 'Pet Care Simulation', 'Virtual pet simulation.', 'Adopt, raise, and bond with a virtual puppy.', 'A charming and accessible pet care simulator.', 'Experience the joy of pet ownership without the mess. Dogz provides a detailed simulation where your interactions directly shape your puppy''s personality and happiness.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dogz-utrashman', 'GAMEBOYADVANCE', 'Dogz (U)(Trashman)', '2005', 'Simulation', 'MTO', '1', 'Pet Care Simulation', 'Virtual pet simulation.', 'Adopt, raise, and bond with a virtual puppy.', 'The US version of the beloved digital pet franchise.', 'Dogz (US) features intuitive controls and colorful graphics. Perfect for younger players, it offers a safe and engaging way to learn about the responsibilities of caring for a dog.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dogz-2-eindependent', 'GAMEBOYADVANCE', 'Dogz 2 (E)(Independent)', '2006', 'Simulation', 'MTO', '1', 'Pet Care Simulation', 'Virtual pet simulation and mini-games.', 'Breed and raise puppies to compete in talent shows.', 'The expanded sequel with more breeds and activities.', 'Dogz 2 improves on the original with more detailed animations and new mini-games. Focus on training your puppies for various challenges to become the top trainer in the neighborhood.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dogz-2-elightforce', 'GAMEBOYADVANCE', 'Dogz 2 (E)(Lightforce)', '2006', 'Simulation', 'MTO', '1', 'Pet Care Simulation', 'Virtual pet simulation and mini-games.', 'Breed and raise puppies to compete in talent shows.', 'The expanded sequel with more breeds and activities.', 'This European release of Dogz 2 features enhanced customization. Decorate your pet''s living space and choose from even more accessories to make your puppy stand out.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dogz-2-urising-sun', 'GAMEBOYADVANCE', 'Dogz 2 (U)(Rising Sun)', '2006', 'Simulation', 'MTO', '1', 'Pet Care Simulation', 'Virtual pet simulation and mini-games.', 'Breed and raise puppies to compete in talent shows.', 'The US version of the feature-rich pet sequel.', 'Dogz 2 (US) brings more breeds and deeper interaction. Track your puppy''s growth and participate in fun activities like fetch and hide-and-seek in this polished simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dokapon---monster-hunter-epatience', 'GAMEBOYADVANCE', 'Dokapon - Monster Hunter (E)(Patience)', '2001', 'RPG', 'Sting', '4', 'Board Game RPG', 'Turn-based RPG and monster collecting.', 'Explore dungeons and defeat monsters to become a Master.', 'A unique RPG mix of dungeon crawling and creature battling.', 'Dokapon - Monster Hunter (Europe) features a charming art style and strategic combat. Collect equipment and capture monsters to aid you in your quest to protect the land from dark forces.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dokapon---monster-hunter-umenace', 'GAMEBOYADVANCE', 'Dokapon - Monster Hunter (U)(Menace)', '2001', 'RPG', 'Sting', '4', 'Board Game RPG', 'Turn-based RPG and monster collecting.', 'Explore dungeons and defeat monsters to become a Master.', 'A unique RPG mix of dungeon crawling and creature battling.', 'The US version of Dokapon offers a deep RPG experience. Navigate perilous dungeons, manage your inventory, and level up your hero in this engaging handheld adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dokapon-q-monster-hunter-jeurasia', 'GAMEBOYADVANCE', 'Dokapon Q Monster Hunter (J)(Eurasia)', '2001', 'RPG', 'Sting', '4', 'Board Game RPG', 'Turn-based RPG and monster collecting.', 'Explore dungeons and defeat monsters to become a Master.', 'The original Japanese release of the Dokapon RPG.', 'Dokapon Q Monster Hunter brings the classic Japanese tactical RPG to the GBA. Experience the original story and mechanics that defined this cult-favorite monster-hunting series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doki-doki-cooking-series-1---komugi-chan-no-happy-cake-jpolla', 'GAMEBOYADVANCE', 'Doki-doki Cooking Series 1 - Komugi-chan no Happy Cake (J)(Polla)', '2004', 'Simulation', 'MTO', '1', 'Cooking Simulation', 'Cooking simulation and mini-games.', 'Follow recipes to bake the perfect cakes and sweets.', 'A cute Japanese cooking adventure starring Komugi-chan.', 'Komugi-chan no Happy Cake is a delightful culinary sim. Master the timing and precision of various baking tasks to satisfy your customers and unlock new recipes in this colorful title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dokodemo-taikyoku-yakuman-advance-jnil', 'GAMEBOYADVANCE', 'Dokodemo Taikyoku Yakuman Advance (J)(Nil)', '2001', 'Board Game', 'Success', '2', 'Mahjong Game', 'Digital Mahjong board game.', 'Master the rules of Mahjong and defeat pro opponents.', 'A polished and portable Japanese Mahjong simulator.', 'Yakuman Advance offers a deep and authentic Mahjong experience. Featuring multiple game modes and challenging AI, it’s the perfect title for fans of the traditional strategic board game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('domo-kun-no-fushigi-terebi-jrapid-fire', 'GAMEBOYADVANCE', 'Domo-Kun no Fushigi Terebi (J)(Rapid Fire)', '2003', 'Adventure', 'Namco', '1', 'TV Character Adventure', 'Mini-game collection and social simulation.', 'Play through a variety of wacky TV-themed challenges.', 'Join the iconic NHK mascot Domo-kun in a fun variety show.', 'Domo-Kun no Fushigi Terebi features diverse mini-games based on television genres. From sports to rhythm games, help Domo-kun navigate his strange digital world in this quirky Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('don-chan-puzzle---hanabi-de-don-jcaravan', 'GAMEBOYADVANCE', 'Don-Chan Puzzle - Hanabi de Don (J)(Caravan)', '2003', 'Puzzle', 'Banpresto', '1', 'Action Puzzle', 'Falling-block puzzle action.', 'Clear the screen by matching colorful fireworks blocks.', 'A frantic puzzle game based on the Hanabi (fireworks) theme.', 'Don-Chan Puzzle (Taiko no Tatsujin spin-off) offers fast-paced matching gameplay. Use the colorful "Don-chan" characters to clear lines and trigger spectacular firework displays in this vibrant Japanese puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donald-duck-advance-eparacox', 'GAMEBOYADVANCE', 'Donald Duck Advance (E)(Paracox)', '2001', 'Platformer', 'Ubisoft', '1', 'Side-Scrolling Platformer', '2D side-scrolling platformer.', 'Navigate magical worlds to rescue Daisy and the nephews.', 'High-energy platforming starring Disney''s famous duck.', 'Donald Duck Advance (Goin'' Quackers) features fluid animations and challenging levels. Use Donald''s temper to your advantage as you battle through diverse environments to save your friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donald-duck-advance-jnobody', 'GAMEBOYADVANCE', 'Donald Duck Advance (J)(Nobody)', '2001', 'Platformer', 'Ubisoft', '1', 'Side-Scrolling Platformer', '2D side-scrolling platformer.', 'Navigate magical worlds to rescue Daisy and the nephews.', 'The original Japanese release of Donald''s platforming quest.', 'Experience Donald Duck Advance in its original GBA format. Relive the cinematic action and clever level design of this Ubisoft-developed Disney classic on your handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donald-duck-advance-uindependent', 'GAMEBOYADVANCE', 'Donald Duck Advance (U)(Independent)', '2001', 'Platformer', 'Ubisoft', '1', 'Side-Scrolling Platformer', '2D side-scrolling platformer.', 'Navigate magical worlds to rescue Daisy and the nephews.', 'The US version of the high-octane Donald Duck adventure.', 'Donald Duck Advance (US) delivers polished 2D platforming. Master Donald''s moves across multiple themed worlds, featuring impressive boss fights and faithful character designs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-emenace', 'GAMEBOYADVANCE', 'Donkey Kong Country (E)(Menace)', '2003', 'Platformer', 'Rare', '2', 'Side-Scrolling Platformer', 'Side-scrolling platformer with pre-rendered 3D.', 'Recover the banana hoard from King K. Rool.', 'The legendary SNES masterpiece reborn on GBA.', 'Donkey Kong Country brings Rare''s iconic platformer to your pocket. Control DK and Diddy through jungles and mines, featuring all the original secrets and updated GBA-exclusive mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-uevasion', 'GAMEBOYADVANCE', 'Donkey Kong Country (U)(Evasion)', '2003', 'Platformer', 'Rare', '2', 'Side-Scrolling Platformer', 'Side-scrolling platformer with pre-rendered 3D.', 'Recover the banana hoard from King K. Rool.', 'The US version of the groundbreaking 16-bit platformer.', 'Experience the definitive handheld version of Donkey Kong Country. With brightened graphics for the GBA screen and new collectibles, it’s the ultimate way to play this classic on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-2-emorrigan', 'GAMEBOYADVANCE', 'Donkey Kong Country 2 (E)(Morrigan)', '2004', 'Platformer', 'Rare', '2', 'Side-Scrolling Platformer', 'Side-scrolling platformer with pre-rendered 3D.', 'Rescue DK from the Kremlings in the Lost World.', 'Diddy and Dixie Kong star in this acclaimed sequel.', 'Donkey Kong Country 2 features complex level design and the "Team-up" mechanic. Explore Crocodile Isle and master Dixie''s helicopter spin in this massive and challenging GBA port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-2-uindependent', 'GAMEBOYADVANCE', 'Donkey Kong Country 2 (U)(Independent)', '2004', 'Platformer', 'Rare', '2', 'Side-Scrolling Platformer', 'Side-scrolling platformer with pre-rendered 3D.', 'Rescue DK from the Kremlings in the Lost World.', 'The US version of the fan-favorite Kong sequel.', 'DKC 2 (US) on GBA includes new boss challenges and a built-in sound test. Navigate treacherous environments and collect all the DK coins in this deep and rewarding platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-3-erising-sun', 'GAMEBOYADVANCE', 'Donkey Kong Country 3 (E)(Rising Sun)', '2005', 'Platformer', 'Rare', '2', 'Side-Scrolling Platformer', 'Side-scrolling platformer with pre-rendered 3D.', 'Find the missing Kongs in the Northern Kremisphere.', 'Dixie and Kiddy Kong take center stage in the trilogy''s finale.', 'Donkey Kong Country 3 features an interactive world map and vehicle-based exploration. Help Dixie and her cousin Kiddy solve the mystery of the "KAOS" robot in this feature-rich GBA port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-3-uindependent', 'GAMEBOYADVANCE', 'Donkey Kong Country 3 (U)(Independent)', '2005', 'Platformer', 'Rare', '2', 'Side-Scrolling Platformer', 'Side-scrolling platformer with pre-rendered 3D.', 'Find the missing Kongs in the Northern Kremisphere.', 'The US version of the final DKC adventure on GBA.', 'DKC 3 (US) includes an entirely new soundtrack and an exclusive world not found in the original SNES version, making it a must-play for series veterans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doom-umode7', 'GAMEBOYADVANCE', 'Doom (U)(Mode7)', '2001', 'Shooter', 'ID Software', '1', 'First-Person Shooter', 'First-person shooter (FPS).', 'Survive the demon-infested Martian base and reach Earth.', 'The groundbreaking FPS classic that defined a genre.', 'Doom for GBA is a technical feat, bringing the fast-paced demon-slaying action to handheld. Navigate through 24 intense levels with a full arsenal of iconic weapons like the Shotgun and BFG9000.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doom-ii-esupplex', 'GAMEBOYADVANCE', 'Doom II (E)(Supplex)', '2004', 'Shooter', 'ID Software', '1', 'First-Person Shooter', 'First-person shooter (FPS).', 'Stop the demon invasion of Earth in this massive sequel.', 'The intense follow-up with more enemies and bigger levels.', 'Doom II (Europe) features the legendary "Super Shotgun" and vast, complex maps. Battle through hordes of hellish creatures in one of the most atmospheric and violent shooters on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doom-ii-umode7', 'GAMEBOYADVANCE', 'Doom II (U)(Mode7)', '2004', 'Shooter', 'ID Software', '1', 'First-Person Shooter', 'First-person shooter (FPS).', 'Stop the demon invasion of Earth in this massive sequel.', 'The US version of the definitive 90s shooter sequel.', 'Doom II (US) on GBA offers fluid gameplay and impressive level architecture. Experience the classic "Hell on Earth" campaign with optimized controls for the handheld''s buttons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dora-the-explorer---doras-world-adventure-usir-vg', 'GAMEBOYADVANCE', 'Dora the Explorer - Dora''s World Adventure (U)(Sir VG)', '2004', 'Adventure', 'Stainless Games', '1', 'Educational Adventure', 'Educational adventure and mini-games.', 'Travel the world to save the day with Dora and Boots.', 'A globe-trotting learning adventure for younger players.', 'Dora''s World Adventure features accessible mini-games that teach geography and culture. Join Dora as she travels to different countries to solve puzzles and help her friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dora-the-explorer---super-spies-urising-sun', 'GAMEBOYADVANCE', 'Dora the Explorer - Super Spies (U)(Rising Sun)', '2004', 'Adventure', 'Stainless Games', '1', 'Educational Adventure', 'Educational adventure and stealth-lite.', 'Use spy gadgets to solve mysteries and stop Swiper.', 'A mission-based adventure featuring Dora''s Super Spy team.', 'Dora the Explorer - Super Spies turns learning into a secret mission. Use gadgets like the Spy Glass and Sneaky Boots to navigate levels and complete educational puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dora-the-explorer---super-star-adventures-urising-sun', 'GAMEBOYADVANCE', 'Dora the Explorer - Super Star Adventures (U)(Rising Sun)', '2003', 'Adventure', 'Stainless Games', '1', 'Educational Adventure', 'Educational adventure and mini-game collection.', 'Collect stars and complete tasks in a magical world.', 'A charming and interactive adventure for Dora fans.', 'Super Star Adventures features various mini-games that focus on memory, logic, and coordination. Help Dora find the special Explorer Stars in this bright and encouraging title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dora-the-explorer---super-star-adventures!-esir-vg', 'GAMEBOYADVANCE', 'Dora the Explorer - Super Star Adventures! (E)(Sir VG)', '2003', 'Adventure', 'Stainless Games', '1', 'Educational Adventure', 'Educational adventure and mini-game collection.', 'Collect stars and complete tasks in a magical world.', 'The European version of the interactive star-hunting quest.', 'This localized version of Super Star Adventures! provides a gentle learning experience. Guide Dora through the Rainforest and beyond while mastering simple, fun challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dora-the-explorer---the-search-for-pirate-pigs-treasure-ueurasia', 'GAMEBOYADVANCE', 'Dora the Explorer - The Search for Pirate Pig''s Treasure (U)(Eurasia)', '2002', 'Adventure', 'Stainless Games', '1', 'Educational Adventure', 'Educational adventure and puzzle platforming.', 'Find the treasure before the Pirate Pig gets there.', 'A fun-filled pirate adventure with Dora and her crew.', 'The Search for Pirate Pig''s Treasure features 2D exploration and simple puzzles. Help Dora navigate the Seven Seas and solve the clues to find the ultimate hidden prize.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doraemon-board-game-jrapid-fire', 'GAMEBOYADVANCE', 'Doraemon Board Game (J)(Rapid Fire)', '2001', 'Board Game', 'Epoch', '4', 'Party Board Game', 'Digital board game.', 'Compete with Doraemon and friends to win the board.', 'A fun, gadget-filled board game starring the robotic cat.', 'Doraemon Board Game features classic tabletop mechanics with a twist. Use Doraemon’s famous secret gadgets to hinder your opponents and navigate the board in this charming Japanese-exclusive title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doraemon-midori-no-wakusei-jperversion', 'GAMEBOYADVANCE', 'Doraemon Midori No Wakusei (J)(Perversion)', '2001', 'Adventure', 'Epoch', '1', 'Story-Based Adventure', 'Action-adventure and RPG.', 'Save the Green Planet from environmental destruction.', 'An eco-friendly adventure featuring Doraemon and Nobita.', 'Doraemon Midori No Wakusei (Green Planet) combines exploration and puzzle-solving. Use gadgets to restore nature and battle enemies in a vibrant world, following an original story based on the beloved anime.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('double-dragon-advance-jrising-sun', 'GAMEBOYADVANCE', 'Double Dragon Advance (J)(Rising Sun)', '2003', 'Action', 'Million', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up.', 'Rescue Marian and defeat the Shadow Warriors.', 'A definitive remake of the legendary arcade brawler.', 'Double Dragon Advance (Japanese version) is widely considered the best entry in the series. It combines moves from the arcade and NES versions, featuring fluid combat, new weapons, and iconic urban stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('double-dragon-advance-umode7', 'GAMEBOYADVANCE', 'Double Dragon Advance (U)(Mode7)', '2003', 'Action', 'Million', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up.', 'Rescue Marian and defeat the Shadow Warriors.', 'A definitive remake of the legendary arcade brawler.', 'The US version of Double Dragon Advance offers high-octane martial arts action. Play as Billy or Jimmy Lee, mastering the new combat mechanics and taking down bosses in this polished GBA action masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doubutsu-no-shima-no-chobi-gurumi-jtrashman', 'GAMEBOYADVANCE', 'Doubutsu no Shima no Chobi Gurumi (J)(Trashman)', '2003', 'Simulation', 'MTO', '1', 'Animal Care Simulation', 'Virtual pet and social simulation.', 'Care for cute animals on a peaceful tropical island.', 'A relaxing animal-care simulation for the GBA.', 'Doubutsu no Shima no Chobi Gurumi allows you to interact with adorable creatures. Manage their happiness, feed them, and explore the island in this cozy and visually soft Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doubutsu-shima-no-chubi-gurumi-2-jcaravan', 'GAMEBOYADVANCE', 'Doubutsu Shima no Chubi Gurumi 2 (J)(Caravan)', '2004', 'Simulation', 'MTO', '1', 'Animal Care Simulation', 'Virtual pet and social simulation.', 'Expand your island and care for even more exotic animals.', 'The charming sequel to the animal island simulation.', 'Doubutsu Shima no Chubi Gurumi 2 features more animal species and improved interaction mini-games. Build a thriving sanctuary and bond with your digital pets in this heartwarming Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('downforce-umode7', 'GAMEBOYADVANCE', 'Downforce (U)(Mode7)', '2003', 'Racing', 'BottleRocket', '4', 'Arcade Racing', 'Formula-style racing simulation.', 'Win the world championship across international tracks.', 'A fast-paced arcade racer with a focus on aerodynamics.', 'Downforce for GBA offers high-speed Formula racing. Master the racing line, manage your pit stops, and outmaneuver rivals on realistic circuits in this technically impressive handheld racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dr-seuss---green-eggs-and-ham-umode7', 'GAMEBOYADVANCE', 'Dr Seuss - Green Eggs and Ham (U)(Mode7)', '2003', 'Platformer', 'NewKidCo', '1', 'Children’s Platformer', 'Educational mini-games and platforming.', 'Explore the world of Dr. Seuss and learn to read.', 'A whimsical learning adventure based on the classic book.', 'Dr. Seuss - Green Eggs and Ham features colorful levels and rhyming puzzles. Help Sam-I-Am navigate through various environments while engaging in educational activities perfect for early readers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dr-muto-eeurasia', 'GAMEBOYADVANCE', 'Dr. Muto (E)(Eurasia)', '2002', 'Action Platformer', 'Midway San Diego', '1', 'Cartoon Action Platformer', '3D-style action platformer and puzzle.', 'Collect the scattered DNA to save your planet.', 'Play as a mad scientist who can morph into different creatures.', 'Dr. Muto features unique transformation mechanics. Change into a spider, mouse, or gorilla to solve environmental puzzles and defeat enemies in this quirky and creative GBA adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dr-seuss---the-cat-in-the-hat-erising-sun', 'GAMEBOYADVANCE', 'Dr. Seuss'' - The Cat in the Hat (E)(Rising Sun)', '2003', 'Platformer', 'Magenta Software', '1', 'Children’s Platformer', '2D side-scrolling platformer.', 'Clean up the house and find the missing fish.', 'A wacky adventure based on the live-action movie.', 'The Cat in the Hat (Europe) lets you use the Cat''s magical umbrella to navigate through chaotic levels. Bounce, float, and solve puzzles to fix the mess before Mom gets home.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dr-seuss---the-cat-in-the-hat-ueurasia', 'GAMEBOYADVANCE', 'Dr. Seuss'' - The Cat in the Hat (U)(Eurasia)', '2003', 'Platformer', 'Magenta Software', '1', 'Children’s Platformer', '2D side-scrolling platformer.', 'Clean up the house and find the missing fish.', 'A wacky adventure based on the live-action movie.', 'The US version of The Cat in the Hat features vibrant graphics and varied mini-games. Explore the surreal world of the Cat and Thing One and Thing Two in this family-friendly GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dr-sudoku-erising-sun', 'GAMEBOYADVANCE', 'Dr. Sudoku (E)(Rising Sun)', '2005', 'Puzzle', 'Zoo Digital', '1', 'Number Puzzle', 'Logic-based puzzle game.', 'Fill the 9x9 grid with numbers following Sudoku rules.', 'A comprehensive Sudoku trainer and puzzle collection.', 'Dr. Sudoku (Europe) features over 600 puzzles ranging from easy to diabolical. Includes a tutorial mode to help beginners master the logic and a puzzle creator for infinite replayability.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dr-sudoku-utrashman', 'GAMEBOYADVANCE', 'Dr. Sudoku (U)(Trashman)', '2005', 'Puzzle', 'Zoo Digital', '1', 'Number Puzzle', 'Logic-based puzzle game.', 'Fill the 9x9 grid with numbers following Sudoku rules.', 'A comprehensive Sudoku trainer and puzzle collection.', 'The US version of Dr. Sudoku offers a clean, user-friendly interface. Test your mental agility with thousands of combinations and improve your solving speed in this portable logic masterclass.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball---advance-adventure-jrising-sun', 'GAMEBOYADVANCE', 'Dragon Ball - Advance Adventure (J)(Rising Sun)', '2004', 'Action Platformer', 'Dimps', '1', 'Anime Action Platformer', 'Side-scrolling action and combat.', 'Relive Goku''s journey from the beginning of Dragon Ball.', 'An incredible action-platformer featuring young Goku.', 'Dragon Ball - Advance Adventure covers the search for the Dragon Balls and the Red Ribbon Army saga. Featuring fluid combat, hover-cloud levels, and 1-on-1 tournament battles, it''s a series highlight.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball---advance-adventure-kindependent', 'GAMEBOYADVANCE', 'Dragon Ball - Advance Adventure (K)(Independent)', '2004', 'Action Platformer', 'Dimps', '1', 'Anime Action Platformer', 'Side-scrolling action and combat.', 'Relive Goku''s journey from the beginning of Dragon Ball.', 'The Korean-localized version of Goku''s early adventures.', 'Experience the high-energy combat of Advance Adventure in this Korean release. Master Goku''s Power Pole and Kamehameha to defeat iconic villains like Mercenary Tao and King Piccolo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball---advanced-adventure-uongaku', 'GAMEBOYADVANCE', 'Dragon Ball - Advanced Adventure (U)(Ongaku)', '2004', 'Action Platformer', 'Dimps', '1', 'Anime Action Platformer', 'Side-scrolling action and combat.', 'Relive Goku''s journey from the beginning of Dragon Ball.', 'The US version of the acclaimed GBA action-adventure.', 'Dragon Ball: Advanced Adventure (US) is praised for its faithful art style and deep combat system. Unlock dozens of characters for the 1v1 mode and explore vast 2D levels in this handheld classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-gt---transformation-utrashman', 'GAMEBOYADVANCE', 'Dragon Ball GT - Transformation (U)(Trashman)', '2005', 'Action Platformer', 'Webfoot Technologies', '1', 'Anime Action Platformer', 'Side-scrolling beat ''em up and shooter.', 'Battle through the GT timeline to defeat Baby.', 'A multi-genre action game based on the Dragon Ball GT anime.', 'Dragon Ball GT: Transformation lets you control Goku, Pan, and Trunks. Fight through waves of enemies in brawler stages or take to the skies in flight-shooter segments to save the galaxy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---bukuu-tougeki-jeurasia', 'GAMEBOYADVANCE', 'Dragon Ball Z - Bukuu Tougeki (J)(Eurasia)', '2004', 'Fighting', 'Cavia', '2', '2D Fighting', '2D aerial fighting game.', 'Win the Budokai tournament with your favorite Z-fighter.', 'A fast-paced fighter known as Supersonic Warriors.', 'Dragon Ball Z - Bukuu Tougeki (Supersonic Warriors) features intense 3-on-3 aerial combat. Experience "What If" storylines and master devastating ultimate attacks in this high-speed Japanese fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---buus-fury-upsychosis', 'GAMEBOYADVANCE', 'Dragon Ball Z - Buu''s Fury (U)(Psychosis)', '2004', 'Action RPG', 'Webfoot Technologies', '1', 'Anime Action RPG', 'Action-RPG with stats and leveling.', 'Defeat Majin Buu and save the universe as a Super Saiyan.', 'The epic conclusion to the Legacy of Goku trilogy.', 'Dragon Ball Z - Buu''s Fury covers the final saga of DBZ. Play as Goku, Vegeta, Gohan, Goten, and Trunks. Featuring fusion mechanics, equipment systems, and massive boss fights, it is the most refined RPG experience in the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---collectible-card-game-umode7', 'GAMEBOYADVANCE', 'Dragon Ball Z - Collectible Card Game (U)(Mode7)', '2004', 'Card Game', 'Digital Eclipse', '2', 'Collectible Card Game', 'Strategic card-based combat.', 'Build the ultimate deck and win the World Martial Arts Tournament.', 'A tactical card game based on the DBZ Collectible Card Game.', 'Dragon Ball Z - Collectible Card Game features deep strategic play. Construct decks using over 140 cards, manage your Ki, and outsmart opponents with strategic positioning and powerful energy blasts in this digital card battle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---supersonic-warriors-erising-sun', 'GAMEBOYADVANCE', 'Dragon Ball Z - Supersonic Warriors (E)(Rising Sun)', '2004', 'Fighting', 'Crafts & Meister', '2', '2D Fighting', '2D aerial fighting game.', 'Win 3-on-3 tag team battles and unlock "What If" stories.', 'High-speed aerial combat known as Supersonic Warriors.', 'DBZ - Supersonic Warriors (Europe) delivers intense 2D fighting. Master the "Flight" mechanic and execute massive team attacks. Explore unique alternate storylines where villains win or unexpected heroes emerge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---supersonic-warriors-kprojectg', 'GAMEBOYADVANCE', 'Dragon Ball Z - Supersonic Warriors (K)(ProjectG)', '2004', 'Fighting', 'Crafts & Meister', '2', '2D Fighting', '2D aerial fighting game.', 'Win 3-on-3 tag team battles and unlock "What If" stories.', 'High-speed aerial combat known as Supersonic Warriors.', 'The Korean-localized version of the hit fighter. Experience the same fast-paced combat and deep roster of Z-Fighters, optimized for handheld play with impressive sprite work and special effects.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---supersonic-warriors-urising-sun', 'GAMEBOYADVANCE', 'Dragon Ball Z - Supersonic Warriors (U)(Rising Sun)', '2004', 'Fighting', 'Crafts & Meister', '2', '2D Fighting', '2D aerial fighting game.', 'Win 3-on-3 tag team battles and unlock "What If" stories.', 'High-speed aerial combat known as Supersonic Warriors.', 'The US version of Supersonic Warriors features the iconic voice cast and high-octane 1v1 or 3v3 battles. Level up your characters to unlock their most powerful transformations and ultimate Ki attacks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---taiketsu-erising-sun', 'GAMEBOYADVANCE', 'Dragon Ball Z - Taiketsu (E)(Rising Sun)', '2003', 'Fighting', 'Webfoot Technologies', '2', 'Anime Fighting', '2D ground-based fighting game.', 'Defeat rivals in the arena to prove you are the strongest.', 'A ground-focused fighter with a massive character roster.', 'Dragon Ball Z - Taiketsu (Europe) offers a different take on DBZ combat. Focus on ground combos and localized special moves in this fighting game featuring characters from across the entire Z timeline.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---taiketsu-urising-sun', 'GAMEBOYADVANCE', 'Dragon Ball Z - Taiketsu (U)(Rising Sun)', '2003', 'Fighting', 'Webfoot Technologies', '2', 'Anime Fighting', '2D ground-based fighting game.', 'Defeat rivals in the arena to prove you are the strongest.', 'A ground-focused fighter with a massive character roster.', 'The US version of Taiketsu features a large variety of modes, including Endurance and Time Attack. Battle with up to 15 different characters in this competitive handheld brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---the-legacy-of-goku-epolla', 'GAMEBOYADVANCE', 'Dragon Ball Z - The Legacy of Goku (E)(Polla)', '2002', 'Action RPG', 'Webfoot Technologies', '1', 'Anime Action RPG', 'Action-RPG with exploration.', 'Save Gohan and defeat Frieza on Planet Namek.', 'The first original DBZ RPG for the Game Boy Advance.', 'Dragon Ball Z - The Legacy of Goku (Europe) lets you experience the Saiyan and Namek sagas. Level up Goku''s stats, master the Kamehameha, and explore iconic locations from the anime in this landmark title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---the-legacy-of-goku-umode7', 'GAMEBOYADVANCE', 'Dragon Ball Z - The Legacy Of Goku (U)(Mode7)', '2002', 'Action RPG', 'Webfoot Technologies', '1', 'Anime Action RPG', 'Action-RPG with exploration.', 'Save Gohan and defeat Frieza on Planet Namek.', 'The first original DBZ RPG for the Game Boy Advance.', 'The US version of Legacy of Goku features the foundational RPG mechanics of the series. Journey through the DBZ story from Raditz to the final showdown with Frieza in this action-packed adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---the-legacy-of-goku-ii-eeurasia', 'GAMEBOYADVANCE', 'Dragon Ball Z - The Legacy of Goku II (E)(Eurasia)', '2003', 'Action RPG', 'Webfoot Technologies', '1', 'Anime Action RPG', 'Action-RPG with multiple characters.', 'Train your heroes and defeat the Androids and Cell.', 'The highly-improved sequel with more playable characters.', 'Legacy of Goku II (Europe) expands the scope significantly. Play as Gohan, Piccolo, Vegeta, and Trunks. Featuring character-specific gates, flight maps, and a deep quest system, it’s a fan-favorite RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---the-legacy-of-goku-ii-utrashman', 'GAMEBOYADVANCE', 'Dragon Ball Z - The Legacy of Goku II (U)(TrashMan)', '2003', 'Action RPG', 'Webfoot Technologies', '1', 'Anime Action RPG', 'Action-RPG with multiple characters.', 'Train your heroes and defeat the Androids and Cell.', 'The highly-improved sequel with more playable characters.', 'The US version of Legacy of Goku II is widely praised for its soundtrack and gameplay balance. Master the Super Saiyan transformations and uncover hidden secrets across a massive world map.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---the-legacy-of-goku-ii-international-jcaravan', 'GAMEBOYADVANCE', 'Dragon Ball Z - The Legacy of Goku II International (J)(Caravan)', '2003', 'Action RPG', 'Webfoot Technologies', '1', 'Anime Action RPG', 'Action-RPG with multiple characters.', 'Train your heroes and defeat the Androids and Cell.', 'The Japanese release of the hit Western-developed RPG.', 'Legacy of Goku II International (Japan) brings the Cell Saga adventure back to the series'' home. Experience the refined RPG mechanics and beautiful sprite art in this localized Japanese edition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z-team-training-v8-new', 'GAMEBOYADVANCE', 'Dragon Ball Z Team Training V8 New', '2020', 'Action RPG', 'Fan Made', '1', 'Monster Training RPG', 'Monster-collecting RPG (Hack).', 'Catch and train over 150 DBZ characters in a Pokémon world.', 'A massive Pokémon FireRed hack featuring DBZ fighters.', 'Dragon Ball Z Team Training V8 replaces Pokémon with Z-Fighters. Each character has unique movesets and "evolutions" (transformations). Explore a modified Kanto region as the ultimate Saiyan Tamer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-drive-jcezar', 'GAMEBOYADVANCE', 'Dragon Drive (J)(Cezar)', '2002', 'Action', 'Game Studio', '1', 'Anime Action', 'Action-adventure and combat.', 'Master your dragon and win the Dragon Drive tournament.', 'High-flying combat based on the Dragon Drive manga.', 'Dragon Drive (Japan) features aerial exploration and intense monster battles. Customize your dragon''s abilities and engage in fast-paced combat to become the top rider in this stylish Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-quest---tornekos-adventure-2-advance-jeurasia', 'GAMEBOYADVANCE', 'Dragon Quest - Torneko''s Adventure 2 Advance (J)(Eurasia)', '2001', 'Roguelike', 'Chunsoft', '1', 'Dungeon Crawler RPG', 'Roguelike dungeon crawler.', 'Navigate the Mysterious Dungeon to find rare treasures.', 'A deep and challenging RPG starring Torneko from Dragon Quest.', 'Torneko''s Adventure 2 (Japan) features turn-based movement and randomized floors. Manage your hunger and inventory while battling classic Dragon Quest monsters in this addictive "Fushigi no Dungeon" entry.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-quest-characters---toruneko-no-daibouken-3-advance---fushigi-no-dungeon-jcaravan', 'GAMEBOYADVANCE', 'Dragon Quest Characters - Toruneko no Daibouken 3 Advance - Fushigi no Dungeon (J)(Caravan)', '2002', 'Roguelike', 'Chunsoft', '1', 'Dungeon Crawler RPG', 'Roguelike dungeon crawler.', 'Survive the dungeon and protect your family''s shop.', 'The expanded third entry in the Torneko spin-off series.', 'Toruneko no Daibouken 3 Advance (Japan) introduces new mechanics and deeper story elements. Master the tactical combat and item management required to survive the deepest levels of the dungeon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-quest-monsters---caravan-heart-jpolla', 'GAMEBOYADVANCE', 'Dragon Quest Monsters - Caravan Heart (J)(Polla)', '2003', 'RPG', 'Tose', '1', 'Monster Collection RPG', 'Monster-battling RPG and caravan management.', 'Lead your caravan across the land to save your parents.', 'A unique Dragon Quest Monsters entry with a focus on travel.', 'Caravan Heart (Japan) stars Prince Kiefer. Instead of just 1-on-1 battles, manage a whole caravan of guardians. Featuring a deep fusion system and a massive world to explore on your GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-tales---dragon-adventures-uchameleon', 'GAMEBOYADVANCE', 'Dragon Tales - Dragon Adventures (U)(Chameleon)', '2006', 'Adventure', 'ImaginEngine', '1', 'Children’s Adventure', 'Educational adventure and mini-games.', 'Help Emmy, Max, and their dragon friends solve puzzles.', 'A friendly learning adventure based on the hit TV show.', 'Dragon Tales - Dragon Adventures (US) features colorful levels and simple puzzles. Join Ord, Cassie, and Zak & Wheezie in activities that promote teamwork and problem-solving for younger players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragons-rock-erising-sun', 'GAMEBOYADVANCE', 'Dragon''s Rock (E)(Rising Sun)', '2004', 'Action Platformer', 'Raylight Studios', '1', 'Fantasy Platformer', '2D side-scrolling platformer.', 'Navigate the dragon''s lair and recover the stolen gems.', 'A fantasy-themed action game with a focus on exploration.', 'Dragon''s Rock (Europe) features classic platforming challenges. Explore dangerous caverns, avoid traps, and defeat mythical creatures in this vibrant and accessible handheld adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragonball-advanced-adventure-erising-sun', 'GAMEBOYADVANCE', 'Dragonball Advanced Adventure (E)(Rising Sun)', '2004', 'Action Platformer', 'Dimps', '1', 'Anime Action Platformer', 'Side-scrolling action and combat.', 'Relive Goku''s journey from the start of the series.', 'The European version of the acclaimed 2D action title.', 'Advanced Adventure (Europe) covers the original Dragon Ball story. Enjoy fluid combat, Power Pole mechanics, and 1v1 tournament modes in one of the most visually impressive games on the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drake-&-josh-urising-sun', 'GAMEBOYADVANCE', 'Drake & Josh (U)(Rising Sun)', '2007', 'Action', 'Behaviour Interactive', '1', 'TV Show Action', 'Mini-game collection and social adventure.', 'Help Drake and Josh manage their chaotic lives.', 'A comedy-filled adventure based on the Nickelodeon show.', 'Drake & Josh (US) features a variety of missions and mini-games reflecting the show''s humor. Help the brothers out of their latest mess through stealth, puzzle-solving, and coordination challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drill-dozer-utrashman', 'GAMEBOYADVANCE', 'Drill Dozer (U)(Trashman)', '2005', 'Action Platformer', 'Game Freak', '1', 'Mechanical Action Platformer', '2D side-scrolling action with drill mechanics.', 'Use your Drill Dozer to break through obstacles and enemies.', 'A unique and creative platformer from the makers of Pokémon.', 'Drill Dozer (US) stars Jill in her transforming mech. Use the L and R buttons to shift gears and drill through everything. Featuring incredible physics and boss fights, it''s a technical masterpiece for the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('driv3r-erising-sun', 'GAMEBOYADVANCE', 'Driv3r (E)(Rising Sun)', '2004', 'Action', 'Reflections Interactive', '1', 'Open-World Driving', 'Isometric driving and mission-based action.', 'Complete high-stakes undercover missions in 3D-style cities.', 'The portable version of the gritty crime-driving series.', 'Driv3r (Europe) pushes the GBA to its limits with 3D city rendering. Perform high-speed chases, shootouts, and stealth missions as Tanner across various international locations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('driv3r-utrashman', 'GAMEBOYADVANCE', 'Driv3r (U)(Trashman)', '2004', 'Action', 'Reflections Interactive', '1', 'Open-World Driving', 'Isometric driving and mission-based action.', 'Complete high-stakes undercover missions in 3D-style cities.', 'The US version of the high-octane driving adventure.', 'Driv3r (US) features intense vehicular combat and open-city exploration. Master the physics of various cars and bikes to complete dangerous undercover operations in this ambitious handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('driven-eroms-world', 'GAMEBOYADVANCE', 'Driven (E)(Roms-World)', '2001', 'Racing', 'SCi', '1', 'Arcade Racing', '3D-style Formula racing.', 'Win the world championship based on the Stallone movie.', 'A fast-paced racing game with high-tech open-wheel cars.', 'Driven (Europe) features realistic physics and diverse tracks. Navigate the professional racing circuit, manage your pit strategy, and outpace rivals in this technically impressive racing simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('driven-umode7', 'GAMEBOYADVANCE', 'Driven (U)(Mode7)', '2001', 'Racing', 'SCi', '1', 'Arcade Racing', '3D-style Formula racing.', 'Win the world championship based on the Stallone movie.', 'The US version of the movie-inspired racing game.', 'Driven (US) offers multiple game modes, including Story and Championship. Experience the speed and tension of open-wheel racing with a focus on precision and drafting mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('driver-2-advance-eeurasia', 'GAMEBOYADVANCE', 'Driver 2 Advance (E)(Eurasia)', '2000', 'Racing', 'Sumo Digital', '1', 'Arcade Driving', 'Isometric driving and open-world missions.', 'Go undercover to dismantle the criminal organization.', 'A massive improvement over the first GBA Driver.', 'Driver 2 Advance (Europe) features impressive 3D city navigation. Explore Chicago and Rio, complete diverse driving missions, and experience a deep undercover story on your GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('driver-2-advance-urdg', 'GAMEBOYADVANCE', 'Driver 2 Advance (U)(RDG)', '2000', 'Racing', 'Sumo Digital', '1', 'Arcade Driving', 'Isometric driving and open-world missions.', 'Go undercover to dismantle the criminal organization.', 'The US version of the definitive GBA Driver experience.', 'Driver 2 Advance (US) delivers fast-paced chases and realistic city layouts. Master the art of the getaway in this technically advanced title that captures the spirit of the console original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('droopys-tennis-open-eeurasia', 'GAMEBOYADVANCE', 'Droopys Tennis Open (E)(Eurasia)', '2002', 'Sports', 'Teque London', '2', 'Cartoon Tennis', 'Sports simulation (Tennis) with cartoon characters.', 'Win the grand slam tournament as Droopy or his friends.', 'A fun and quirky tennis game featuring MGM characters.', 'Droopys Tennis Open features accessible controls and specialized "super shots." Compete across various court types and master the timing of your volleys in this charming and competitive sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dual-blades-jcezar', 'GAMEBOYADVANCE', 'Dual Blades (J)(Cezar)', '2004', 'Action', 'Future Games', '1', 'Side-Scrolling Action', '2D weapon-based fighting game.', 'Win the tournament using unique blades and magic.', 'A brutal and fast-paced fighter with a fantasy theme.', 'Dual Blades (Japan) features a deep combo system and unique "Power" mechanics. Choose from a roster of mystical warriors and master their specialized weaponry in this intense handheld brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dual-blades-uvenom', 'GAMEBOYADVANCE', 'Dual Blades (U)(Venom)', '2004', 'Action', 'Future Games', '1', 'Side-Scrolling Action', '2D weapon-based fighting game.', 'Win the tournament using unique blades and magic.', 'The US version of the high-energy weapon fighter.', 'Dual Blades (US) offers fluid animations and challenging AI. Battle through the story mode to uncover the mystery of the Dual Blades in this polished and visually striking fighting game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('duel-master-3-jcaravan', 'GAMEBOYADVANCE', 'Duel Master 3 (J)(Caravan)', '2003', 'Card Battle', 'KCEJ', '2', 'Trading Card Battle', 'Strategic card-battling RPG.', 'Build your deck and become the Kaijudo Master.', 'The third entry in the popular Japanese card game series.', 'Duel Master 3 (Japan) features expanded card sets and refined battle mechanics. Explore the world, challenge other duelists, and master the art of summoning powerful creatures in this deep strategic title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('duel-masters---kaijudo-showdown-eendless-piracy', 'GAMEBOYADVANCE', 'Duel Masters - Kaijudo Showdown (E)(Endless Piracy)', '2004', 'Card Battle', 'AM Entertainment', '2', 'Trading Card Battle', 'Strategic card-battling RPG.', 'Build a powerful deck to win the Kaijudo tournament.', 'A deep tactical card game based on the hit series.', 'Duel Masters - Kaijudo Showdown (Europe) features an expansive card library and strategic turn-based duels. Explore the world, interact with characters from the anime, and master the Five Civilizations to become a Kaijudo master.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('duel-masters---kaijudo-showdown-uvenom', 'GAMEBOYADVANCE', 'Duel Masters - Kaijudo Showdown (U)(Venom)', '2004', 'Card Battle', 'AM Entertainment', '2', 'Trading Card Battle', 'Strategic card-battling RPG.', 'Build a powerful deck to win the Kaijudo tournament.', 'A deep tactical card game based on the hit series.', 'The US version of Kaijudo Showdown offers refined deck-building mechanics. Collect rare cards and participate in high-stakes duels where mana management and shield-breaking strategy are key to victory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('duel-masters---sempai-legends-erising-sun', 'GAMEBOYADVANCE', 'Duel Masters - Sempai Legends (E)(Rising Sun)', '2004', 'Card Battle', 'AM Entertainment', '2', 'Trading Card Battle', 'Strategic card-battling RPG.', 'Travel the land and win the Sempai Legends title.', 'The first western release of the Duel Masters GBA series.', 'Duel Masters - Sempai Legends introduces the core mechanics of the card game. Build your inventory of cards through exploration and prove your skills against legendary duelists in this story-driven RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('duel-masters---sempai-legends-uvenom', 'GAMEBOYADVANCE', 'Duel Masters - Sempai Legends (U)(Venom)', '2004', 'Card Battle', 'AM Entertainment', '2', 'Trading Card Battle', 'Strategic card-battling RPG.', 'Travel the land and win the Sempai Legends title.', 'The first western release of the Duel Masters GBA series.', 'The US version of Sempai Legends features a faithful recreation of the card game rules. Master the balance between Light, Water, Darkness, Fire, and Nature civilizations in this portable strategic adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('duel-masters---shadow-of-the-code-erising-sun', 'GAMEBOYADVANCE', 'Duel Masters - Shadow Of The Code (E)(Rising Sun)', '2005', 'Card Battle', 'AM Entertainment', '2', 'Trading Card Battle', 'Strategic card-battling RPG.', 'Uncover the mystery of the Code and win duels.', 'The third installment in the western Duel Masters series.', 'Shadow Of The Code (Europe) features over 400 cards and an updated interface. Engage in a complex story while fine-tuning your deck to counter increasingly difficult AI opponents in professional tournaments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('duel-masters---shadow-of-the-code-utrashman', 'GAMEBOYADVANCE', 'Duel Masters - Shadow of the Code (U)(Trashman)', '2005', 'Card Battle', 'AM Entertainment', '2', 'Trading Card Battle', 'Strategic card-battling RPG.', 'Uncover the mystery of the Code and win duels.', 'The third installment in the western Duel Masters series.', 'The US version of Shadow of the Code offers the most comprehensive card-battling experience on GBA. With improved deck-editing tools and a vast world, it''s the definitive title for Duel Masters fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('duel-masters-jrising-sun', 'GAMEBOYADVANCE', 'Duel Masters (J)(Rising Sun)', '2002', 'Card Battle', 'AM Entertainment', '2', 'Trading Card Battle', 'Strategic card-battling RPG.', 'Defeat rivals to become the top Japanese duelist.', 'The original Japanese debut of the Duel Masters franchise.', 'Experience where the digital legend began. This Japanese release features the early card sets and a vibrant world map where players must challenge NPCs to earn better cards and progress the story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('duel-masters-2---kirifuda-shoubu-version-jcaravan', 'GAMEBOYADVANCE', 'Duel Masters 2 - Kirifuda Shoubu Version (J)(Caravan)', '2003', 'Card Battle', 'AM Entertainment', '2', 'Trading Card Battle', 'Strategic card-battling RPG.', 'Master the Kirifuda Shoubu style of dueling.', 'An expanded Japanese sequel with exclusive cards.', 'Duel Masters 2 - Kirifuda Shoubu Version features refined 2D art and faster duel pacing. Utilize character-specific strategies and build a deck that reflects your own playstyle in this Japanese gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('duel-masters-2-jrising-sun', 'GAMEBOYADVANCE', 'Duel Masters 2 (J)(Rising Sun)', '2003', 'Card Battle', 'AM Entertainment', '2', 'Trading Card Battle', 'Strategic card-battling RPG.', 'Win the national tournament and collect rare spirits.', 'The core sequel in the Japanese Duel Masters series.', 'Duel Masters 2 (Japan) introduces more cards and improved AI. Navigate through diverse regions, participate in specialized card shop tournaments, and collect every rare creature in the game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('duke-nukem-advance-elightforce', 'GAMEBOYADVANCE', 'Duke Nukem Advance (E)(LightForce)', '2002', 'Shooter', 'Torpedo Games', '1', 'First-Person Shooter', 'First-person shooter (FPS).', 'Fight through 19 levels to stop the alien invasion.', 'An original and technically impressive Duke Nukem title.', 'Duke Nukem Advance is one of the GBA''s best shooters. Battle through global locations like Egypt and Australia, using a full arsenal of weapons to clear out the alien scum in this fast-paced action hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('duke-nukem-advance-ueurasia', 'GAMEBOYADVANCE', 'Duke Nukem Advance (U)(Eurasia)', '2002', 'Shooter', 'Torpedo Games', '1', 'First-Person Shooter', 'First-person shooter (FPS).', 'Fight through 19 levels to stop the alien invasion.', 'An original and technically impressive Duke Nukem title.', 'The US version of Duke Nukem Advance features fluid 3D graphics and classic Duke humor. Experience the "Mighty Foot" and powerful weaponry in a game designed specifically for the GBA''s capabilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dungeons-and-dragons---eye-of-the-beholder-epatience', 'GAMEBOYADVANCE', 'Dungeons and Dragons - Eye of the Beholder (E)(Patience)', '2002', 'RPG', 'Westwood Studios', '1', 'Dungeon Crawler RPG', 'First-person dungeon crawler RPG.', 'Lead a party of four through the Sewers of Waterdeep.', 'A GBA remake of the classic D&D computer RPG.', 'Dungeons and Dragons - Eye of the Beholder brings 3rd Edition rules to a retro format. Manage your party''s classes and spells as you navigate treacherous grids and battle iconic monsters in a deep fantasy quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dungeons-and-dragons---eye-of-the-beholder-uvenom', 'GAMEBOYADVANCE', 'Dungeons and Dragons - Eye of the Beholder (U)(Venom)', '2002', 'RPG', 'Westwood Studios', '1', 'Dungeon Crawler RPG', 'First-person dungeon crawler RPG.', 'Lead a party of four through the Sewers of Waterdeep.', 'A GBA remake of the classic D&D computer RPG.', 'The US version of Eye of the Beholder offers a challenging strategic experience. Map out complex dungeons, solve environmental puzzles, and engage in tactical turn-based combat in this definitive portable D&D adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dynasty-warriors-advance-erising-sun', 'GAMEBOYADVANCE', 'Dynasty Warriors Advance (E)(Rising Sun)', '2005', 'Action', 'Koei', '1', 'Hack and Slash', 'Tactical hack-and-slash action.', 'Lead your army to victory across ancient China.', 'A handheld spin-off of the massive Dynasty Warriors series.', 'Dynasty Warriors Advance features grid-based movement and intense 2D combat. Control legendary generals like Zhao Yun, managing battlefield morale and capturing strongholds to dominate the Three Kingdoms.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dynasty-warriors-advance-uindependent', 'GAMEBOYADVANCE', 'Dynasty Warriors Advance (U)(Independent)', '2005', 'Action', 'Koei', '1', 'Hack and Slash', 'Tactical hack-and-slash action.', 'Lead your army to victory across ancient China.', 'A handheld spin-off of the massive Dynasty Warriors series.', 'The US version of Dynasty Warriors Advance combines strategic planning with fast-paced fighting. Level up your officers and collect powerful weapons to turn the tide of war in this expansive portable title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('et-the-extra-terrestrial-eblizzard', 'GAMEBOYADVANCE', 'E.T. The Extra-Terrestrial (E)(Blizzard)', '2002', 'Action', 'Sensory Sweep', '1', 'Movie Tie-in Action', 'Adventure and mini-game collection.', 'Help E.T. phone home and avoid the government agents.', 'A heartwarming adventure based on the Spielberg classic.', 'E.T. The Extra-Terrestrial for GBA features exploration and stealth. Help Elliott and E.T. find the parts for the communicator while avoiding capture in a series of levels that mirror the iconic movie plot.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('et-the-extra-terrestrial-umode7', 'GAMEBOYADVANCE', 'E.T. The Extra-Terrestrial (U)(Mode7)', '2002', 'Action', 'Sensory Sweep', '1', 'Movie Tie-in Action', 'Adventure and mini-game collection.', 'Help E.T. phone home and avoid the government agents.', 'A heartwarming adventure based on the Spielberg classic.', 'The US version of E.T. offers family-friendly gameplay with a focus on puzzle-solving. Use E.T.''s special powers to heal plants and outsmart the authorities in this colorful handheld adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthworm-jim-umode7', 'GAMEBOYADVANCE', 'Earthworm Jim (U)(Mode7)', '2001', 'Platformer', 'Shiny Entertainment', '1', 'Run and Gun Platformer', 'Surreal 2D action platformer.', 'Save Princess What''s-Her-Name from Psy-Crow.', 'A port of the wacky and highly stylized 16-bit hit.', 'Earthworm Jim brings the bizarre humor and creative level design of the original to GBA. Master the whip-like movements of Jim''s head and navigate through "New Junk City" in this challenging and unique platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthworm-jim-2-epatience', 'GAMEBOYADVANCE', 'Earthworm Jim 2 (E)(Patience)', '2002', 'Platformer', 'Shiny Entertainment', '1', 'Run and Gun Platformer', 'Surreal 2D action platformer.', 'Battle through strange worlds to find the secret ending.', 'The even weirder sequel to the legendary worm''s quest.', 'Earthworm Jim 2 (Europe) features diverse gameplay styles, including flight segments and isometric puzzles. Use Snot the snail as a parachute and navigate through levels like "Puppy Love" in this cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthworm-jim-2-umode7', 'GAMEBOYADVANCE', 'Earthworm Jim 2 (U)(Mode7)', '2002', 'Platformer', 'Shiny Entertainment', '1', 'Run and Gun Platformer', 'Surreal 2D action platformer.', 'Battle through strange worlds to find the secret ending.', 'The even weirder sequel to the legendary worm''s quest.', 'The US version of Earthworm Jim 2 offers vibrant graphics and the series'' signature offbeat humor. Test your platforming skills across some of the most creative and difficult stages ever designed for handhelds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ecks-vs-sever-eindependent', 'GAMEBOYADVANCE', 'Ecks vs. Sever (E)(Independent)', '2001', 'Shooter', 'Crawfish Interactive', '2', 'First-Person Shooter', 'First-person shooter (FPS).', 'Complete covert operations as Ecks or Sever.', 'A high-quality FPS based on the action film.', 'Ecks vs. Sever (Europe) is a technical powerhouse on the GBA. Choose your operative and navigate through realistic urban environments, completing objectives and eliminating targets with a wide range of firearms.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ecks-vs-sever-umode7', 'GAMEBOYADVANCE', 'Ecks vs. Sever (U)(Mode7)', '2001', 'Shooter', 'Crawfish Interactive', '2', 'First-Person Shooter', 'First-person shooter (FPS).', 'Complete covert operations as Ecks or Sever.', 'A high-quality FPS based on the action film.', 'The US version of Ecks vs. Sever features impressive 3D rendering and smooth controls. Experience intense firefights and tactical missions in a game that proved the GBA could handle professional FPS gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ed-edd-n-eddy---the-mis-edventures-eindependent', 'GAMEBOYADVANCE', 'Ed Edd n Eddy - The Mis-Edventures (E)(Independent)', '2005', 'Platformer', 'Artificial Mind & Movement', '1', 'Cartoon Platformer', '2D side-scrolling platformer and brawler.', 'Complete the ultimate scam to earn enough for Jawbreakers.', 'Join the Eds in their most chaotic neighborhood caper.', 'Ed Edd n Eddy - The Mis-Edventures (Europe) captures the show''s art style perfectly. Switch between the three Eds to utilize their unique abilities and complete wacky missions in the cul-de-sac.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ed-edd-n-eddy---jawbreakers!-eindependent', 'GAMEBOYADVANCE', 'Ed, Edd n Eddy - Jawbreakers! (E)(Independent)', '2002', 'Platformer', 'Crawfish Interactive', '1', 'Cartoon Platformer', '2D side-scrolling platformer.', 'Navigate through 12 levels to find the legendary candy.', 'A fast-paced and funny platformer based on the cartoon.', 'Ed, Edd n Eddy - Jawbreakers! (Europe) features slapstick action and puzzles. Help the trio overcome neighborhood hazards and outsmart the other kids to reach the ultimate sugary prize at the end of each stage.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ed-edd-n-eddy---jawbreakers!-ueurasia', 'GAMEBOYADVANCE', 'Ed, Edd n Eddy - Jawbreakers! (U)(Eurasia)', '2002', 'Platformer', 'Crawfish Interactive', '1', 'Cartoon Platformer', '2D side-scrolling platformer.', 'Navigate through 12 levels to find the legendary candy.', 'A fast-paced and funny platformer based on the cartoon.', 'The US version of Jawbreakers! offers challenging platforming and iconic sound effects from the show. Master the "Scam" system to unlock secrets and navigate the hazards of Peach Creek.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ed-edd-n-eddy---jawbreakers!-usir-vg', 'GAMEBOYADVANCE', 'Ed, Edd n Eddy - Jawbreakers! (U)(Sir VG)', '2002', 'Platformer', 'Crawfish Interactive', '1', 'Cartoon Platformer', '2D side-scrolling platformer.', 'Navigate through 12 levels to find the legendary candy.', 'A fast-paced and funny platformer based on the cartoon.', 'This US release by Sir VG ensures a smooth experience. Each level is a tribute to the show''s humor, requiring players to think like an Ed to overcome the obstacles and find the Jawbreakers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ed-edd-n-eddy---the-mis-edventures-utrashman', 'GAMEBOYADVANCE', 'Ed, Edd n Eddy - The Mis-Edventures (U)(Trashman)', '2005', 'Platformer', 'Artificial Mind & Movement', '1', 'Cartoon Platformer', '2D side-scrolling platformer and brawler.', 'Complete the ultimate scam to earn enough for Jawbreakers.', 'Join the Eds in their most chaotic neighborhood caper.', 'The US version of The Mis-Edventures features diverse gameplay, including brawling and puzzle-solving. Use the Eds'' teamwork to navigate school and neighborhood settings in this faithful animated adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('egg-mania-umode7', 'GAMEBOYADVANCE', 'Egg Mania (U)(Mode7)', '2002', 'Puzzle', 'HotGen', '1', 'Action Puzzle', 'Falling-block puzzle with a water-rising twist.', 'Build a tower of blocks to stay above the rising tide.', 'A frantic and unique spin on the puzzle genre.', 'Egg Mania (US) requires speed and strategy. Build your structure quickly and use power-ups to sabotage your opponents as you try to stay dry in this competitive and addictive handheld puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eggmania-tsukande!-mawashite!-dossun-puzzle-jevasion', 'GAMEBOYADVANCE', 'EggMania Tsukande! Mawashite! Dossun Puzzle (J)(Evasion)', '2002', 'Puzzle', 'HotGen', '1', 'Action Puzzle', 'Falling-block puzzle with a water-rising twist.', 'Build a tower of blocks to stay above the rising tide.', 'The original Japanese release of the egg-stacking hit.', 'EggMania Tsukande! (Japan) features quirky characters and intense puzzle action. Master the timing of your block placement to outlast the competition in this vibrant and high-energy Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eggo-mania-erdg', 'GAMEBOYADVANCE', 'Eggo Mania (E)(RDG)', '2002', 'Puzzle', 'HotGen', '1', 'Action Puzzle', 'Falling-block puzzle with a water-rising twist.', 'Build a tower of blocks to stay above the rising tide.', 'The European version of the high-stakes puzzle game.', 'Eggo Mania (Europe) offers various game modes, including a deep tournament path. Battle against AI or friends to prove you have the best tower-building skills under pressure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eigo-kobuhen-eijukugo-hen-650-phrases-blue-edition-jmugs', 'GAMEBOYADVANCE', 'Eigo Kobuhen Eijukugo Hen 650 Phrases Blue Edition (J)(Mugs)', '2003', 'Educational', 'Nintendo', '1', 'English Learning', 'Educational / Language Tutor.', 'Master 650 English idioms and phrases.', 'An English language learning tool for Japanese speakers.', 'Eigo Kobuhen: Blue Edition is a specialized educational title for the GBA. It features interactive quizzes and 650 essential English idioms, designed to help Japanese students improve their vocabulary and grammar on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eigo-kubunhen-jindependent', 'GAMEBOYADVANCE', 'Eigo Kubunhen (J)(Independent)', '2002', 'Educational', 'Nintendo', '1', 'English Grammar Training', 'Educational / Language Tutor.', 'Improve English reading and comprehension skills.', 'A portable English language study guide for the GBA.', 'Eigo Kubunhen provides a structured way to study English. Using the GBA’s interface, players can practice sentence structure and translation through a series of progressively difficult lessons and tests.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eitangohen---2000-words-jmugs', 'GAMEBOYADVANCE', 'Eitangohen - 2000 Words (J)(Mugs)', '2003', 'Educational', 'Nintendo', '1', 'Vocabulary Training', 'Educational / Language Tutor.', 'Memorize 2000 common English words.', 'A comprehensive English vocabulary trainer for GBA.', 'Eitangohen: 2000 Words is a robust study aid. It uses a flashcard-style system to help users master a large bank of English vocabulary, making it one of the most content-rich educational tools on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elemix-jpolla', 'GAMEBOYADVANCE', 'Elemix (J)(Polla)', '2004', 'Puzzle', 'Jupiter', '1', 'Action Puzzle', 'Puzzle / Strategy.', 'Clear the board by matching elemental orbs.', 'A colorful Japanese puzzle game with a fantasy theme.', 'Elemix combines fast-paced matching with strategic planning. Use different elemental powers to clear obstacles and achieve high scores in this vibrant, Japan-exclusive handheld puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elevator-action---old-&-new-jeurasia', 'GAMEBOYADVANCE', 'Elevator Action - Old & New (J)(Eurasia)', '2003', 'Action', 'Taito', '1', 'Arcade Action', '2D Action / Platformer.', 'Infiltrate buildings and escape via the elevator.', 'A remake of the Taito classic with modern graphics.', 'Elevator Action: Old & New offers both the original 1983 arcade experience and a "New" mode with updated sprites, new characters, and enhanced mechanics. Sneak through high-rises and outsmart enemy spies in this definitive portable edition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elf---the-movie-uvenom', 'GAMEBOYADVANCE', 'Elf - The Movie (U)(Venom)', '2004', 'Action', 'Human Soft', '1', 'Movie Tie-in Action', '2D Side-scrolling Platformer.', 'Help Buddy find his father in New York City.', 'A festive adventure based on the hit Christmas movie.', 'Elf: The Movie for GBA features Buddy the Elf in a series of whimsical levels. Navigate the North Pole and the streets of New York, collecting ornaments and spreading Christmas cheer in this family-friendly platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elf-bowling-1-&-2-utrashman', 'GAMEBOYADVANCE', 'Elf Bowling 1 & 2 (U)(Trashman)', '2005', 'Party', 'GameHouse', '4', 'Casual Party Games', 'Sports / Arcade.', 'Hit as many elves as possible with a bowling ball.', 'A controversial and quirky holiday-themed sports pack.', 'Elf Bowling 1 & 2 brings the internet viral sensation to the GBA. Play traditional bowling with a twisted holiday theme or enjoy the shuffleboard-style sequel in this unique and humorous collection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elf-the-movie-eindependent', 'GAMEBOYADVANCE', 'Elf The Movie (E)(Independent)', '2004', 'Action', 'Human Soft', '1', 'Movie Tie-in Action', '2D Side-scrolling Platformer.', 'Help Buddy find his father in New York City.', 'European version of the holiday movie adaptation.', 'This localized version of Elf The Movie offers the same charming gameplay. Solve simple puzzles and navigate platforming challenges as Buddy, featuring iconic locations and characters from the film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('emerald-cross-v21', 'GAMEBOYADVANCE', 'Emerald Cross v2.1', 'Unknown', 'Action', 'Fan Made', '1', 'Sonic Battle Mod', 'Monster-collecting RPG (Hack).', 'Explore a modified Hoenn with new challenges.', 'An updated fan-made expansion of Pokémon Emerald.', 'Emerald Cross v2.1/v3.5 is a quality-of-life hack of the classic RPG. It includes modern features like the Physical/Special split, updated movepools, and increased difficulty for a more competitive experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('emerald-cross-v35', 'GAMEBOYADVANCE', 'Emerald Cross v3.5', 'Unknown', 'Action', 'Fan Made', '1', 'Sonic Battle Mod', 'Monster-collecting RPG (Hack).', 'Explore a modified Hoenn with new challenges.', 'An updated fan-made expansion of Pokémon Emerald.', 'This advanced version of the Emerald Cross hack offers even more features, including follower Pokémon, custom UI elements, and a broader variety of catchable monsters from later generations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('emerald-the-hedgehog12345!-in-sonic-battle', 'GAMEBOYADVANCE', 'Emerald the Hedgehog12345! in sonic battle', 'Unknown', 'Action', 'Fan Made', '1', 'Sonic Battle Mod', '2D Arena Fighting (Hack).', 'Fight as Emerald the Hedgehog in combat arenas.', 'A character replacement hack for Sonic Battle.', 'Emerald the Hedgehog brings a new custom character to the Sonic Battle roster. Featuring a unique green aesthetic and modified move animations, it’s a creative treat for fans of the Sonic hacking scene.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('emerald-trashlocke-edition', 'GAMEBOYADVANCE', 'Emerald Trashlocke Edition', 'Unknown', 'Action', 'Fan Made', '1', 'Sonic Battle Mod', 'Monster-collecting RPG (Hack).', 'Survive the Hoenn region under "Trashlocke" rules.', 'A hardcore difficulty hack with weak Pokémon only.', 'Emerald Trashlocke Edition is designed for veterans. It removes all "overpowered" Pokémon from the game, forcing you to win the championship using only the weakest species in a high-stakes Nuzlocke challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('emerald-uncensored-beta-2', 'GAMEBOYADVANCE', 'Emerald Uncensored Beta 2', 'Unknown', 'Action', 'Fan Made', '1', 'Sonic Battle Mod', 'Monster-collecting RPG (Hack).', 'Experience Emerald without the original censorship.', 'A hack that restores original Japanese sprites and text.', 'Emerald Uncensored Beta 2 aims to provide the original vision of the game. It restores sprites, animations, and dialogue that were changed for the Western release, offering a more "authentic" experience for purists.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('enchanted---once-upon-andalasia-usir-vg', 'GAMEBOYADVANCE', 'Enchanted - Once Upon Andalasia (U)(Sir VG)', '2007', 'Adventure', 'Altron', '1', 'Story Adventure', 'Isometric Adventure / Puzzle.', 'Help Giselle navigate New York and find her way home.', 'A magical adventure based on the Disney film.', 'Enchanted: Once Upon Andalasia features a mix of 2D and isometric gameplay. Switch between characters to solve puzzles and explore both the animated world and the real-world city in this charming movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eragon-erising-sun', 'GAMEBOYADVANCE', 'Eragon (E)(Rising Sun)', '2006', 'Action', 'Backbone Entertainment', '1', 'Action Adventure', 'Isometric Action / Adventure.', 'Master the art of dragon riding and defeat Galbatorix.', 'A fantasy epic based on the movie and novel.', 'Eragon for GBA features intense melee combat and spellcasting. Level up Eragon’s skills and use Saphira the dragon to overcome waves of enemies in this detailed and atmospheric adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eragon-urising-sun', 'GAMEBOYADVANCE', 'Eragon (U)(Rising Sun)', '2006', 'Action', 'Backbone Entertainment', '1', 'Action Adventure', 'Isometric Action / Adventure.', 'Master the art of dragon riding and defeat Galbatorix.', 'The US version of the dragon-riding fantasy adventure.', 'The US release of Eragon delivers fluid isometric combat. Explore the land of Alagaësia, collect hidden items, and master the bond between rider and dragon in this faithful adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('erementar-gerad-jsupplex', 'GAMEBOYADVANCE', 'Erementar Gerad (J)(Supplex)', '2005', 'RPG', 'MediaWorks', '1', 'Action RPG', '2D Fighting / Action.', 'Use the power of the Elemental Gerad to win battles.', 'A Japanese fighter based on the popular manga/anime.', 'Erementar Gerad (Elemental Gelade) features high-speed combat and "Pledge" mechanics where characters link up for powerful attacks. Experience the story through beautiful sprite work and intense 1v1 duels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-final-round-golf-eparacox', 'GAMEBOYADVANCE', 'ESPN Final Round Golf (E)(Paracox)', '2001', 'Sports', 'Kemco', '4', 'Golf Simulation', 'Sports / Golf Simulation.', 'Win the professional golf tour across realistic courses.', 'A deep and technical golf game endorsed by ESPN.', 'ESPN Final Round Golf features realistic wind physics and terrain effects. Master your swing timing and club selection to climb the leaderboards in this polished handheld sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-final-round-golf-2002-umode7', 'GAMEBOYADVANCE', 'ESPN Final Round Golf 2002 (U)(Mode7)', '2002', 'Sports', 'Kemco', '4', 'Golf Simulation', 'Sports / Golf Simulation.', 'Win the professional golf tour across realistic courses.', 'The 2002 US edition of the ESPN golf franchise.', 'ESPN Final Round Golf 2002 offers multiple game modes, including a deep career path. Customize your golfer and compete on various international courses with professional-style commentary and presentation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-great-outdoor-games---bass-2002-umode7', 'GAMEBOYADVANCE', 'ESPN Great Outdoor Games - Bass 2002 (U)(Mode7)', '2002', 'Sports', 'Kemco', '4', 'Fishing Simulation', 'Sports / Fishing Simulation.', 'Catch the biggest bass and win the tournament.', 'A realistic outdoor sports game for fishing enthusiasts.', 'ESPN Great Outdoor Games: Bass 2002 features multiple lakes, a variety of lures, and realistic fish AI. Manage your boat and equipment to find the best fishing spots in this relaxing but competitive sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-great-outdoor-games---bass-tournament-elightforce', 'GAMEBOYADVANCE', 'ESPN Great Outdoor Games - Bass Tournament (E)(Lightforce)', '2002', 'Sports', 'Kemco', '4', 'Fishing Simulation', 'Sports / Fishing Simulation.', 'Catch the biggest bass and win the tournament.', 'European edition of the ESPN bass fishing title.', 'This localized version offers the same deep fishing mechanics. Compete against the clock and other pro anglers to secure the top spot in the Bass Tournament rankings.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-international---winter-sports-etrashman', 'GAMEBOYADVANCE', 'ESPN International - Winter Sports (E)(TrashMan)', '2002', 'Sports', 'Kemco', '4', 'Winter Sports Compilation', 'Sports / Winter Games.', 'Win gold in various winter sporting events.', 'A comprehensive winter sports compilation by ESPN.', 'ESPN International Winter Sports features events like Ski Jumping, Speed Skating, and Bobsledding. Master the unique controls for each event to lead your country to victory on the global stage.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-international---winter-sports-2002-umode7', 'GAMEBOYADVANCE', 'ESPN International - Winter Sports 2002 (U)(Mode7)', '2002', 'Sports', 'Kemco', '4', 'Winter Sports Compilation', 'Sports / Winter Games.', 'Win gold in various winter sporting events.', 'The 2002 US edition of the ESPN winter sports sim.', 'ESPN International Winter Sports 2002 offers a broadcast-style experience on the GBA. Practice each event in trial mode before entering the full Olympic-style competition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-winter-x-games---snowboarding-2-eindependent', 'GAMEBOYADVANCE', 'ESPN Winter X-Games - Snowboarding 2 (E)(Independent)', '2003', 'Sports', 'Vicarious Visions', '4', 'Snowboarding', 'Sports / Snowboarding.', 'Land massive tricks and win the snowboarding circuit.', 'High-flying snowboarding action with a pro focus.', 'ESPN Winter X-Games Snowboarding 2 features improved physics and more complex trick combinations. Carve through icy slopes and master the half-pipe to impress the judges and earn sponsorships.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-winter-x-games---snowboarding-2002-jeurasia', 'GAMEBOYADVANCE', 'ESPN Winter X-Games - Snowboarding 2002 (J)(Eurasia)', '2002', 'Sports', 'Vicarious Visions', '4', 'Snowboarding', 'Sports / Snowboarding.', 'Land massive tricks and win the snowboarding circuit.', 'The Japanese release of the X-Games snowboarding hit.', 'This Japanese version features the same intense downhill action. Compete in Big Air, Slopestyle, and Superpipe events, utilizing the GBA''s buttons to pull off legendary stunts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-winter-x-games---snowboarding-2002-umode7', 'GAMEBOYADVANCE', 'ESPN Winter X-Games - Snowboarding 2002 (U)(Mode7)', '2002', 'Sports', 'Vicarious Visions', '4', 'Snowboarding', 'Sports / Snowboarding.', 'Land massive tricks and win the snowboarding circuit.', 'The 2002 US edition of the ESPN snowboarding franchise.', 'ESPN Winter X-Games Snowboarding 2002 delivers fast-paced arcade racing and trick-heavy gameplay. Unlock new boards and gear as you progress through the professional X-Games tour.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-x-games---skateboarding-epatience', 'GAMEBOYADVANCE', 'ESPN X-Games - Skateboarding (E)(Patience)', '2001', 'Sports', 'Vicarious Visions', '4', 'Skateboarding', 'Sports / Skateboarding.', 'Complete skate challenges and land epic combos.', 'A Tony Hawk-style skater with the ESPN X-Games license.', 'ESPN X-Games Skateboarding features real-world locations and professional skaters. Master grinds, flips, and vert tricks to achieve high scores and complete various mission-based objectives.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-x-games---skateboarding-jnil', 'GAMEBOYADVANCE', 'ESPN X-Games - Skateboarding (J)(Nil)', '2001', 'Sports', 'Vicarious Visions', '4', 'Skateboarding', 'Sports / Skateboarding.', 'Complete skate challenges and land epic combos.', 'The original Japanese release of the X-Games skater.', 'Experience the thrill of the X-Games on your GBA. This Japanese edition features responsive controls and a variety of urban environments to shred, from schoolyards to professional skate parks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-x-games---skateboarding-umode7', 'GAMEBOYADVANCE', 'ESPN X-Games - Skateboarding (U)(Mode7)', '2001', 'Sports', 'Vicarious Visions', '4', 'Skateboarding', 'Sports / Skateboarding.', 'Complete skate challenges and land epic combos.', 'The US version of the ESPN skateboarding title.', 'The US release of ESPN X-Games Skateboarding offers a robust career mode. Customize your skater''s stats and gear to take on the world''s most difficult rails and ramps.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('estopolis-densetsu-jeurasia', 'GAMEBOYADVANCE', 'Estopolis Densetsu (J)(Eurasia)', '1998', 'RPG', 'Neverland', '1', 'Turn-Based RPG', 'Turn-based RPG.', 'Follow Maxim on a quest to stop the Sinistrals.', 'A Japanese remake of the legendary Lufia series.', 'Estopolis Densetsu (Lufia: The Legend Returns) features a unique "Ancient Cave" mode and a deep turn-based combat system. Manage a large party of heroes in this epic fantasy RPG known for its emotional story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('european-super-league-efett1', 'GAMEBOYADVANCE', 'European Super League (E)(Fett1)', '2001', 'Sports', 'Eidos Interactive', '4', 'Soccer Simulation', 'Soccer simulation and management.', 'Lead your team to the top of the elite European league.', 'A strategic and fast-paced soccer sim for GBA.', 'European Super League lets you compete with the biggest clubs in Europe. Manage your tactics and master the on-field action to win the most prestigious trophy in continental football.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('evergirl-utrashman', 'GAMEBOYADVANCE', 'Evergirl (U)(Trashman)', '2005', 'Action', 'DC Studios', '1', 'Teen Adventure', 'Social simulation and mini-games.', 'Express your personality and complete fashion challenges.', 'A creative lifestyle game based on the Evergirl brand.', 'Evergirl for GBA focuses on friendship and self-expression. Take personality quizzes, design outfits, and participate in various social activities in this vibrant and positive handheld experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ex-monopoly-jeurasia', 'GAMEBOYADVANCE', 'EX Monopoly (J)(Eurasia)', '2002', 'Board Game', 'Takara', '4', 'Digital Board Game', 'Digital board game.', 'Bankrupt your opponents and own the entire board.', 'An enhanced Japanese version of the classic Monopoly.', 'EX Monopoly brings the world-famous property trading game to GBA with polished graphics. Play against smart AI or friends in this definitive handheld edition of the classic board game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('exciting-bass-jgbatemp', 'GAMEBOYADVANCE', 'Exciting Bass (J)(GBATemp)', '2001', 'Sports', 'Kemco', '4', 'Fishing Simulation', 'Sports / Fishing simulation.', 'Catch the rarest and heaviest bass in Japan''s lakes.', 'A realistic and technical Japanese fishing game.', 'Exciting Bass (known as Big Bass in the West) offers a deep fishing experience. Choose your equipment carefully and master the tension of the line to reel in massive trophy fish.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('expedition-der-stachelbeeren-zoff-im-zoo-grising-sun', 'GAMEBOYADVANCE', 'Expedition Der Stachelbeeren Zoff Im Zoo (G)(Rising Sun)', '2004', 'Adventure', 'Independent Arts', '1', 'Kids Adventure', 'Adventure and mini-game collection.', 'Save the animals and stop the zoo chaos.', 'German-localized adventure starring The Wild Thornberrys.', 'Zoff Im Zoo (Wild Thornberrys: Zoo Rescuer) features Eliza and her family. Use her ability to talk to animals to solve puzzles and navigate the zoo in this charming educational adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('extreme-ghostbusters---code-ecto-1-eeurasia', 'GAMEBOYADVANCE', 'Extreme Ghostbusters - Code Ecto-1 (E)(Eurasia)', '2004', 'Action', 'Vicarious Visions', '1', 'Action Adventure', 'Side-scrolling action and driving.', 'Capture ghosts and stop the spectral invasion of NYC.', 'A high-energy action game based on the Extreme Ghostbusters.', 'Extreme Ghostbusters - Code Ecto-1 features a mix of on-foot platforming and Ecto-1 driving levels. Use specialized proton packs to trap ghosts and save New York in this atmospheric action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('extreme-ghostbusters---code-ecto-1-uindependent', 'GAMEBOYADVANCE', 'Extreme Ghostbusters - Code Ecto-1 (U)(Independent)', '2004', 'Action', 'Vicarious Visions', '1', 'Action Adventure', 'Side-scrolling action and driving.', 'Capture ghosts and stop the spectral invasion of NYC.', 'The US version of the spectral superhero adventure.', 'Code Ecto-1 (US) offers challenging combat and diverse gadgets. Play as Roland or Kylie, utilizing their unique skills to navigate spooky environments and defeat massive boss ghosts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('extreme-mahjong-deluxe---terminator-21-jeurasia', 'GAMEBOYADVANCE', 'Extreme Mahjong Deluxe - Terminator 21 (J)(Eurasia)', '2002', 'Board Game', 'Success', '1', 'Mahjong', 'Digital Mahjong / Board game.', 'Defeat 21 opponents to become the Mahjong champion.', 'A competitive and stylized Japanese Mahjong simulator.', 'Extreme Mahjong Deluxe features fast-paced rules and a "terminator" style elimination tournament. Master the tiles and outsmart the AI in this polished handheld board game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eyeshield-21---devilbats-devildays-jcaravan', 'GAMEBOYADVANCE', 'Eyeshield 21 - Devilbats Devildays (J)(Caravan)', '2004', 'Sports', 'KCEJ', '1', 'Sports Anime', 'Sports-RPG / Mini-games.', 'Train with the Devilbats to win the Christmas Bowl.', 'A sports-adventure based on the Eyeshield 21 anime.', 'Devilbats Devildays features training mini-games and story segments. Help Sena and the team improve their American Football skills through various challenges in this high-energy Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ez-talk-1-jcezar', 'GAMEBOYADVANCE', 'EZ-Talk 1 (J)(Cezar)', '2001', 'Educational', 'Nintendo', '1', 'Language Learning', 'Educational / Language Tutor.', 'Learn basic English vocabulary and grammar.', 'An interactive English learning series for Japanese speakers.', 'EZ-Talk 1 is the first entry in a robust language learning suite. Using the GBA''s audio capabilities, it teaches essential English phrases through interactive lessons and pronunciation guides.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ez-talk-2-jcezar', 'GAMEBOYADVANCE', 'EZ-Talk 2 (J)(Cezar)', '2001', 'Educational', 'Nintendo', '1', 'Language Learning', 'Educational / Language Tutor.', 'Expand your English conversation skills.', 'The second volume of the GBA English tutor series.', 'EZ-Talk 2 builds upon the basics with more complex sentence structures and daily conversation scenarios, making language learning accessible and portable for GBA users.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ez-talk-3-jcezar', 'GAMEBOYADVANCE', 'EZ-Talk 3 (J)(Cezar)', '2001', 'Educational', 'Nintendo', '1', 'Language Learning', 'Educational / Language Tutor.', 'Master travel-related English phrases.', 'The third volume of the GBA English tutor series.', 'EZ-Talk 3 focuses on practical English for travel and shopping. Practice common interactions through quizzes and listening exercises in this specialized educational title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ez-talk-4-jcezar', 'GAMEBOYADVANCE', 'EZ-Talk 4 (J)(Cezar)', '2001', 'Educational', 'Nintendo', '1', 'Language Learning', 'Educational / Language Tutor.', 'Improve business and professional English.', 'The fourth volume of the GBA English tutor series.', 'EZ-Talk 4 targets professional communication. Learn how to navigate office environments and formal meetings using this interactive handheld study guide.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ez-talk-5-jnobody', 'GAMEBOYADVANCE', 'EZ-Talk 5 (J)(Nobody)', '2002', 'Educational', 'Nintendo', '1', 'Language Learning', 'Educational / Language Tutor.', 'Advanced English grammar and listening.', 'The fifth volume of the GBA English tutor series.', 'EZ-Talk 5 offers challenging content for advanced students. Focus on nuance and complex listening comprehension in this detailed language education tool.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ez-talk-6-jcezar', 'GAMEBOYADVANCE', 'EZ-Talk 6 (J)(Cezar)', '2002', 'Educational', 'Nintendo', '1', 'Language Learning', 'Educational / Language Tutor.', 'Final mastery of English conversation.', 'The final volume of the GBA English tutor series.', 'EZ-Talk 6 completes the curriculum. Test your total knowledge with comprehensive exams and simulated conversations to prove your English proficiency.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-14-tomcat-umode7', 'GAMEBOYADVANCE', 'F-14 Tomcat (U)(Mode7)', '2001', 'Simulation', 'Electronic Arts', '1', 'Flight Combat', 'Flight combat simulation.', 'Complete dangerous sorties and engage in dogfights.', 'High-speed aerial combat featuring the iconic F-14.', 'F-14 Tomcat for GBA delivers arcade-style flight action. Take off from carriers, manage your weapons systems, and shoot down enemy MiGs in this intense military simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-18-super-hornet-urising-sun', 'GAMEBOYADVANCE', 'F-18 Super Hornet (U)(Rising Sun)', '2003', 'Simulation', 'Electronic Arts', '1', 'Flight Combat', 'Flight combat simulation.', 'Pilot the Super Hornet through global conflict zones.', 'A realistic military flight simulator for the GBA.', 'F-18 Super Hornet features diverse mission objectives and technical flight controls. Master landing on carriers and engaging in multi-target combat in this impressive handheld flight sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-zero---climax-japan-t-en-by-normmatt-v10', 'GAMEBOYADVANCE', 'F-Zero - Climax (Japan) [T-En by Normmatt v1.0]', '2004', 'Racing', 'Nintendo', '1', 'Futuristic Racing', 'Futuristic high-speed racing.', 'Win the 24th-century Grand Prix across 50+ tracks.', 'The fan-translated version of the ultimate F-Zero game.', 'F-Zero Climax [English Patch] allows fans to enjoy the series'' most content-rich entry. Featuring a track editor and refined Boost mechanics, it’s the peak of 2D futuristic racing on GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-zero---falcon-densetsu-jeurasia', 'GAMEBOYADVANCE', 'F-Zero - Falcon Densetsu (J)(Eurasia)', '2003', 'Racing', 'Nintendo', '1', 'Futuristic Racing', 'Futuristic high-speed racing.', 'Follow the anime story and win the high-speed races.', 'The Japanese version of F-Zero GP Legend.', 'F-Zero: Falcon Densetsu ties directly into the animated series. Experience the story through the eyes of Rick Wheeler and Captain Falcon in this high-octane racing masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-zero---maximum-velocity-umode7', 'GAMEBOYADVANCE', 'F-Zero - Maximum Velocity (U)(Mode7)', '2001', 'Racing', 'Nintendo', '1', 'Futuristic Racing', 'Futuristic high-speed racing.', 'Outpace rivals in the fastest racing circuit in the galaxy.', 'The debut F-Zero title for the Game Boy Advance.', 'F-Zero: Maximum Velocity features new pilots and tracks. Experience the raw speed and challenging handling that defined the GBA launch, pushing the system''s hardware with Mode-7 style effects.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-zero-jindependent', 'GAMEBOYADVANCE', 'F-Zero (J)(Independent)', '2001', 'Racing', 'Nintendo', '1', 'Futuristic Racing', 'Futuristic high-speed racing.', 'Outpace rivals in the fastest racing circuit in the galaxy.', 'The original Japanese release of Maximum Velocity.', 'F-Zero for GBA brings the legendary SNES racing feel to your pocket. Master the "power slide" and navigate treacherous turns at over 400 km/h in this iconic Japanese racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-zero-climax-jeurasia', 'GAMEBOYADVANCE', 'F-Zero Climax (J)(Eurasia)', '2004', 'Racing', 'Nintendo', '1', 'Futuristic Racing', 'Futuristic high-speed racing.', 'Win the Grand Prix and create your own circuits.', 'The final and most advanced F-Zero title on GBA.', 'F-Zero Climax (Japan) is a technical marvel. It features a robust track editor, a massive roster of pilots, and the most refined physics engine in the GBA trilogy, making it a must-play for racing fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-zero-gp-legend-erising-sun', 'GAMEBOYADVANCE', 'F-Zero GP Legend (E)(Rising Sun)', '2003', 'Racing', 'Nintendo', '1', 'Futuristic Racing', 'Futuristic high-speed racing.', 'Stop the Dark Million and win the GP Legend circuit.', 'High-speed racing with a deep, character-driven story.', 'F-Zero GP Legend (Europe) features multiple story paths and intense "Boost to Win" gameplay. Unlock hidden pilots and master every circuit in this polished and cinematic racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-zero-gp-legend-urising-sun', 'GAMEBOYADVANCE', 'F-Zero GP Legend (U)(Rising Sun)', '2003', 'Racing', 'Nintendo', '1', 'Futuristic Racing', 'Futuristic high-speed racing.', 'Stop the Dark Million and win the GP Legend circuit.', 'The US version of the anime-inspired racing hit.', 'F-Zero GP Legend (US) offers fluid 60fps gameplay and challenging AI. Battle through the "Story" and "Grand Prix" modes to prove you are the fastest pilot in the galaxy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f1-2002-eadvance-power', 'GAMEBOYADVANCE', 'F1 2002 (E)(Advance-Power)', '2002', 'Racing', 'Electronic Arts', '2', 'Formula One Racing', 'Formula 1 racing simulation.', 'Win the FIA World Championship as your favorite driver.', 'A realistic and licensed F1 experience for the GBA.', 'F1 2002 features all the official teams, drivers, and tracks from the season. Master the technical aspects of F1 racing, including fuel management and tire wear, in this detailed sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f1-2002-ueurasia', 'GAMEBOYADVANCE', 'F1 2002 (U)(Eurasia)', '2002', 'Racing', 'Electronic Arts', '2', 'Formula One Racing', 'Formula 1 racing simulation.', 'Win the FIA World Championship as your favorite driver.', 'The US version of the official Formula 1 sim.', 'Experience the speed of F1 2002 on your handheld. Navigate the tight corners of Monaco and the straights of Monza with precise controls and impressive sprite-scaling graphics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f24---stealth-fighter-urising-sun', 'GAMEBOYADVANCE', 'F24 - Stealth Fighter (U)(Rising Sun)', '2003', 'Simulation', 'Jaleco', '1', 'Flight Combat', 'Flight combat simulation.', 'Infiltrate enemy airspace and destroy strategic targets.', 'A stealth-focused military flight action game.', 'F24 Stealth Fighter features mission-based aerial combat. Pilot the world''s most advanced stealth jet, managing your radar signature while taking down enemy installations and aircraft.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fairly-oddparents---clash-with-the-anti-world-erising-sun', 'GAMEBOYADVANCE', 'Fairly Oddparents - Clash with the Anti-World (E)(Rising Sun)', '2004', 'Action', 'Altron', '1', 'Cartoon Action', '2D side-scrolling platformer.', 'Save Dimmsdale from the evil Anti-Cosmo and his army.', 'A magical adventure based on the hit Nickelodeon show.', 'Fairly Oddparents: Clash with the Anti-World features Timmy Turner using magical wishes to overcome puzzles and enemies. Explore the flipped Anti-World and rescue your fairy godparents in this fun platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-mini---vol-10---star-soldier-jrising-sun', 'GAMEBOYADVANCE', 'Famicom Mini - Vol 10 - Star Soldier (J)(Rising Sun)', '2004', 'Shooter', 'Nintendo', '1', 'Arcade Shooter', 'Vertical-scrolling shoot ''em up.', 'Destroy the Starbrain and the invading alien fleet.', 'A perfect GBA port of the classic NES shooter.', 'Famicom Mini: Star Soldier brings intense 8-bit space combat to your handheld. Navigate through 16 stages of bullet-filled action, collecting power-ups to upgrade your ship''s fire rate and reach the final boss.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-mini---vol-12---clu-clu-land-jhyperion', 'GAMEBOYADVANCE', 'Famicom Mini - Vol 12 - Clu Clu Land (J)(Hyperion)', '2004', 'Puzzle', 'Nintendo', '2', 'Classic Puzzle', 'Grid-based puzzle and action.', 'Uncover all the hidden gold bars in each stage.', 'A unique 8-bit puzzle game featuring Bubbles.', 'Famicom Mini: Clu Clu Land challenges your reflexes. Swing around poles to navigate the grid and reveal hidden patterns in this faithful recreation of the quirky Nintendo original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-mini---vol-13---balloon-fight-jhyperion', 'GAMEBOYADVANCE', 'Famicom Mini - Vol 13 - Balloon Fight (J)(Hyperion)', '2004', 'Action', 'Nintendo', '2', 'Arcade Action', 'Single-screen arcade action.', 'Pop the enemies'' balloons while staying afloat.', 'The legendary gravity-based arcade hit on GBA.', 'Famicom Mini: Balloon Fight features both the classic endless "Balloon Trip" and the 2-player battle mode. Master the unique flapping physics to avoid lightning and hungry fish in this 8-bit gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-mini---vol-14---wrecking-crew-jhyperion', 'GAMEBOYADVANCE', 'Famicom Mini - Vol 14 - Wrecking Crew (J)(Hyperion)', '2004', 'Action', 'Nintendo', '1', 'Arcade Action', 'Puzzle platformer.', 'Destroy all the walls and objects without getting trapped.', 'A strategic demolition game starring Mario.', 'Famicom Mini: Wrecking Crew tasks you with clearing 100 levels of debris. Outsmart Foreman Spike and avoid enemies in this clever logic-based platformer from Nintendo''s early years.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-mini---vol-16---dig-dug-jhyperion', 'GAMEBOYADVANCE', 'Famicom Mini - Vol 16 - Dig Dug (J)(Hyperion)', '2004', 'Action', 'Nintendo', '1', 'Arcade Action', 'Arcade maze and puzzle.', 'Defeat all underground monsters by inflating them.', 'The classic Namco arcade hit, perfectly ported.', 'Famicom Mini: Dig Dug lets you dig your own tunnels to trap Pookas and Fygar. Use your pump to pop enemies or drop rocks on them in this timeless and addictive arcade conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-mini---vol-17---takahashi-meijin-no-bouken-jima-jhyperion', 'GAMEBOYADVANCE', 'Famicom Mini - Vol 17 - Takahashi Meijin no Bouken Jima (J)(Hyperion)', '2004', 'Platformer', 'Nintendo', '1', 'Classic Platformer', '2D side-scrolling platformer.', 'Rescue Princess Leilani from the Evil Witch Doctor.', 'The 8-bit adventure of Master Higgins.', 'Famicom Mini: Takahashi Meijin no Bouken Jima (Adventure Island) is a challenging platformer where you must manage your hunger by collecting fruit while dodging snails and fire pits on a tropical island.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-mini---vol-18---makaimura-jhyperion', 'GAMEBOYADVANCE', 'Famicom Mini - Vol 18 - Makaimura (J)(Hyperion)', '2004', 'Action', 'Nintendo', '1', 'Action Platformer', '2D side-scrolling action platformer.', 'Rescue the Princess from the demon realm.', 'The notoriously difficult NES classic, Ghosts ''n Goblins.', 'Famicom Mini: Makaimura brings Arthur’s perilous journey to GBA. Battle zombies and demons while trying to keep your armor intact in one of the most challenging 8-bit games ever made.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-mini---vol-19---twinbee-jhyperion', 'GAMEBOYADVANCE', 'Famicom Mini - Vol 19 - TwinBee (J)(Hyperion)', '2004', 'Shooter', 'Nintendo', '2', 'Vertical Shooter', 'Vertical-scrolling shoot ''em up.', 'Protect the world from the Spice King''s army.', 'A colorful and cute 8-bit shooter from Konami.', 'Famicom Mini: TwinBee features the unique bell-power-up system. Juggle bells with your shots to change their color and gain specialized upgrades in this charming and vibrant arcade port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-mini---vol-2---donkey-kong-jrising-sun', 'GAMEBOYADVANCE', 'Famicom Mini - Vol 2 - Donkey Kong (J)(Rising Sun)', '2004', 'Platformer', 'Nintendo', '2', 'Classic Platformer', 'Single-screen arcade platformer.', 'Rescue Pauline from the giant ape at the top.', 'The legendary debut of Mario and Donkey Kong.', 'Famicom Mini: Donkey Kong is a pixel-perfect recreation of the game that started it all. Jump over barrels and climb ladders across four iconic stages to save the damsel in distress.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-mini---vol-20---ganbare-goemon!-karakuri-douchuu-jhyperion', 'GAMEBOYADVANCE', 'Famicom Mini - Vol 20 - Ganbare Goemon! Karakuri Douchuu (J)(Hyperion)', '2004', 'Action', 'Nintendo', '1', 'Action Adventure', '2D action-adventure and exploration.', 'Travel across Japan to stop the evil Hannya.', 'The debut of the legendary Goemon (Mystical Ninja).', 'Famicom Mini: Ganbare Goemon! Karakuri Douchuu features top-down exploration and 2D action. Visit shops, talk to NPCs, and defeat enemies with your pipe in this foundational Japanese classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-mini---vol-22---nazo-no-murasame-jcaravan', 'GAMEBOYADVANCE', 'Famicom Mini - Vol 22 - Nazo no Murasame (J)(Caravan)', '2004', 'Action', 'Nintendo', '1', 'Action Adventure', 'Top-down action-adventure.', 'Defeat the demonic army and solve the castle mystery.', 'A cult classic 8-bit samurai adventure.', 'Famicom Mini: Nazo no Murasame Jou features fast-paced sword and shuriken combat. Navigate the labyrinthine Murasame Castle to defeat alien-controlled lords in this high-energy Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-mini---vol-23---metroid-jcaravan', 'GAMEBOYADVANCE', 'Famicom Mini - Vol 23 - Metroid (J)(Caravan)', '2004', 'Action', 'Nintendo', '1', 'Action Adventure', '2D non-linear action-platformer.', 'Defeat Mother Brain and the Space Pirates on Zebes.', 'The revolutionary 8-bit origin of the Metroidvania genre.', 'Famicom Mini: Metroid brings Samus Aran’s first mission to GBA. Explore the depths of Planet Zebes, find the Ice Beam and Screw Attack, and experience the atmospheric sci-fi classic anywhere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-mini---vol-24---hikari-shinwa---palutena-no-kagame-jcaravan', 'GAMEBOYADVANCE', 'Famicom Mini - Vol 24 - Hikari Shinwa - Palutena no Kagame (J)(Caravan)', '2004', 'Action', 'Nintendo', '1', 'Action Adventure', '2D platformer and vertical shooter.', 'Rescue the goddess Palutena and defeat Medusa.', 'The original Kid Icarus adventure from the NES.', 'Famicom Mini: Hikari Shinwa (Kid Icarus) features Pit in a multi-genre quest. Climb out of the Underworld and collect the Three Sacred Treasures in this unique and challenging 8-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-mini---vol-25---link-no-bouken-jcaravan', 'GAMEBOYADVANCE', 'Famicom Mini - Vol 25 - Link no Bouken (J)(Caravan)', '2004', 'Action', 'Nintendo', '1', 'Action Adventure', 'Side-scrolling action-RPG.', 'Wake Princess Zelda from an eternal slumber.', 'The controversial and unique sequel, Zelda II.', 'Famicom Mini: Link no Bouken (Zelda II: The Adventure of Link) mixes top-down exploration with side-scrolling combat. Level up your magic and sword skills to conquer the Great Palace in this difficult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-mini---vol-26---mukashi-hanashi---shin-onigashima-jcaravan', 'GAMEBOYADVANCE', 'Famicom Mini - Vol 26 - Mukashi Hanashi - Shin Onigashima (J)(Caravan)', '2004', 'Adventure', 'Nintendo', '1', 'Text Adventure', 'Visual novel and adventure.', 'Solve the folklore-inspired mystery of Onigashima.', 'A classic Nintendo Disk System text adventure.', 'Famicom Mini: Shin Onigashima features a rich story based on Japanese fairy tales. Use the command-based interface to interact with the world and solve puzzles in this beautifully written 8-bit narrative.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-mini---vol-27---famicom-tantei-club---kieta-koukeisha-jcaravan', 'GAMEBOYADVANCE', 'Famicom Mini - Vol 27 - Famicom Tantei Club - Kieta Koukeisha (J)(Caravan)', '2004', 'Adventure', 'Nintendo', '1', 'Text Adventure', 'Mystery visual novel / Adventure.', 'Uncover the truth behind a wealthy family''s disappearance.', 'The first entry in the acclaimed Famicom Detective Club.', 'Famicom Mini: Famicom Tantei Club (The Missing Heir) is a dark and engaging mystery. Interview suspects and search for clues to solve a complex murder case in this foundational detective game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-mini---vol-28---famicom-tantei-club-part-ii---ushiro-ni-tatsu-shoujo-zengouhen-jcaravan', 'GAMEBOYADVANCE', 'Famicom Mini - Vol 28 - Famicom Tantei Club Part II - Ushiro ni Tatsu Shoujo Zengouhen (J)(Caravan)', '2004', 'Adventure', 'Nintendo', '1', 'Text Adventure', 'Mystery visual novel / Adventure.', 'Solve the urban legend of the "Girl in the Back."', 'The haunting and cinematic sequel to the detective series.', 'Famicom Mini: Famicom Tantei Club Part II (The Girl Who Stands Behind) delivers a tense atmosphere and psychological horror. Experience one of the NES''s best-written stories on your handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-mini---vol-29---akumajo-dracula-jcaravan', 'GAMEBOYADVANCE', 'Famicom Mini - Vol 29 - Akumajo Dracula (J)(Caravan)', '2004', 'Action', 'Nintendo', '1', 'Action Platformer', 'Side-scrolling action platformer.', 'Enter the castle and defeat Count Dracula.', 'The iconic debut of the Castlevania series.', 'Famicom Mini: Akumajo Dracula brings Simon Belmont''s whip-cracking action to GBA. Master the sub-weapons and battle through classic horror movie monsters to reach the final showdown with Death and Dracula.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-mini---vol-3---ice-climber-jrising-sun', 'GAMEBOYADVANCE', 'Famicom Mini - Vol 3 - Ice Climber (J)(Rising Sun)', '2004', 'Platformer', 'Nintendo', '2', 'Classic Platformer', 'Single-screen vertical platformer.', 'Scale the mountain to reclaim your stolen vegetables.', 'A charming and difficult 8-bit climbing classic.', 'Famicom Mini: Ice Climber features Popo and Nana. Use your hammer to break blocks and avoid polar bears as you race to the top of 32 different mountains in this faithful NES recreation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-mini---vol-30---sd-gundam-world-gachapon-senshi---scramble-wars-jcaravan', 'GAMEBOYADVANCE', 'Famicom Mini - Vol 30 - SD Gundam World Gachapon Senshi - Scramble Wars (J)(Caravan)', '2004', 'Strategy', 'Nintendo', '2', 'Tactical Strategy', 'Strategic board game and combat.', 'Defeat enemy Gundams and conquer the map.', 'A mix of strategy and action featuring SD Gundam.', 'Famicom Mini: SD Gundam World features tactical movement and real-time combat segments. Command your fleet and engage in 1v1 battles to control the territory in this 8-bit strategy classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-mini---vol-4---excite-bike-jindependent', 'GAMEBOYADVANCE', 'Famicom Mini - Vol 4 - Excite Bike (J)(Independent)', '2004', 'Racing', 'Nintendo', '1', 'Arcade Racing', 'Side-scrolling dirt bike racing.', 'Race against the clock and rivals on obstacle courses.', 'The high-flying 8-bit motocross classic.', 'Famicom Mini: Excite Bike features the iconic track editor and overheat mechanics. Manage your speed and landing angle to clear jumps and secure the fastest time in this legendary Nintendo racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-mini---vol-6---pacman-jrising-sun', 'GAMEBOYADVANCE', 'Famicom Mini - Vol 6 - Pacman (J)(Rising Sun)', '2004', 'Action', 'Nintendo', '2', 'Arcade Action', 'Arcade maze and puzzle.', 'Eat all the dots while avoiding the four ghosts.', 'The most famous arcade game of all time on GBA.', 'Famicom Mini: Pacman is a perfect port of the pellet-munching legend. Use Power Pellets to turn the tide against Blinky, Pinky, Inky, and Clyde in this timeless and endlessly replayable classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-mini---vol-7---xevious-jrising-sun', 'GAMEBOYADVANCE', 'Famicom Mini - Vol 7 - Xevious (J)(Rising Sun)', '2004', 'Shooter', 'Nintendo', '2', 'Arcade Shooter', 'Vertical-scrolling shoot ''em up.', 'Destroy the Andor Genesis and the invading GAMP forces.', 'The revolutionary 8-bit shooter from Namco.', 'Famicom Mini: Xevious features a dual-attack system: fire at air targets and bomb ground installations. Experience the game that defined the modern Shmup genre in its original 8-bit glory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-mini---vol-8---mappy-jrising-sun', 'GAMEBOYADVANCE', 'Famicom Mini - Vol 8 - Mappy (J)(Rising Sun)', '2004', 'Action', 'Nintendo', '2', 'Arcade Action', 'Arcade maze and action.', 'Recover the stolen goods from the Meowky gang.', 'A charming and rhythmic 8-bit police chase.', 'Famicom Mini: Mappy stars the brave police mouse. Use trampolines to move between floors and avoid the cats while collecting loot in this fun and upbeat Namco classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-mini---vol-9---bomberman-jrising-sun', 'GAMEBOYADVANCE', 'Famicom Mini - Vol 9 - Bomberman (J)(Rising Sun)', '2004', 'Action', 'Nintendo', '4', 'Arcade Action', 'Grid-based action puzzle.', 'Destroy all enemies and find the exit before time runs out.', 'The explosive 8-bit debut of the Bomberman series.', 'Famicom Mini: Bomberman brings the original grid-clearing gameplay to your pocket. Upgrade your blast radius and bomb count to navigate through 50 levels of strategic destruction.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('family-feud-urising-sun', 'GAMEBOYADVANCE', 'Family Feud (U)(Rising Sun)', '2006', 'Game Show', 'Atomic Planet', '4', 'Party Trivia', 'Trivia and game show.', 'Answer survey questions to win the family prize.', 'The official handheld version of the popular TV show.', 'Family Feud for GBA captures the fun of the classic game show. Play through multiple rounds, including "Fast Money," as you try to guess the most popular answers to everyday questions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('family-tennis-advance-jeurasia', 'GAMEBOYADVANCE', 'Family Tennis Advance (J)(Eurasia)', '2002', 'Sports', 'Namco', '4', 'Tennis Simulation', 'Sports simulation (Tennis).', 'Win the tournament against various family members.', 'A charming and colorful Japanese tennis game.', 'Family Tennis Advance features responsive controls and a fun cast of characters. Master the timing of your shots and climb the rankings in this accessible and polished sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famista-advance-jindependent', 'GAMEBOYADVANCE', 'Famista Advance (J)(Independent)', '2001', 'Sports', 'Namco', '4', 'Baseball Simulation', 'Sports simulation (Baseball).', 'Lead your team to victory in the national league.', 'The definitive GBA entry in the popular Famista series.', 'Famista Advance features deep baseball mechanics and a vast roster of players. Manage your pitching rotation and batting order to dominate the league in this classic Japanese baseball sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fancy-pocket-jmugs', 'GAMEBOYADVANCE', 'Fancy Pocket (J)(Mugs)', '2000', 'Simulation', 'Nintendo', '1', 'Virtual Pet', 'Social simulation / Mini-games.', 'Design clothes and manage your own boutique.', 'A cute and creative fashion game for Japanese fans.', 'Fancy Pocket features fashion design and shop management. Interact with customers, create unique styles, and grow your business in this visually charming and accessible handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantasic-marchen-keekiyasan-monogatari-and-doubutsu-charanavi-uranai-koseishinrigaku-jevasion', 'GAMEBOYADVANCE', 'Fantasic Marchen Keekiyasan Monogatari and Doubutsu CharaNavi Uranai Koseishinrigaku (J)(Evasion)', '2002', 'Simulation', 'Nintendo', '1', 'Life Simulation', 'Mini-game collection and astrology.', 'Learn your personality and play cooking-themed games.', 'A unique blend of lifestyle tools and arcade games.', 'Fantasic Marchen Keekiyasan (Cake Shop Story) features bakery-themed mini-games alongside a "CharaNavi" personality profiling system based on Japanese psychology and astrology.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantastic-4---flame-on-eindependent', 'GAMEBOYADVANCE', 'Fantastic 4 - Flame On (E)(Independent)', '2005', 'Action', 'Seven Studios', '2', 'Beat ''em up', 'Side-scrolling action platformer.', 'Control the Human Torch to stop the Skrull invasion.', 'A solo adventure starring Johnny Storm of the Fantastic 4.', 'Fantastic 4 - Flame On (Europe) focuses on high-speed flight and fire-based combat. Master Johnny Storm''s heat powers to burn through enemies and navigate hazardous levels in this action-packed handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantastic-4---flame-on-utrashman', 'GAMEBOYADVANCE', 'Fantastic 4 - Flame on (U)(Trashman)', '2005', 'Action', 'Seven Studios', '2', 'Beat ''em up', 'Side-scrolling action platformer.', 'Control the Human Torch to stop the Skrull invasion.', 'A solo adventure starring Johnny Storm of the Fantastic 4.', 'The US version of Flame On features intense aerial maneuvers and boss fights. Use your flame-throwing abilities to defeat robotic threats and save the city in this specialized Marvel superhero game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantastic-4-eindependent', 'GAMEBOYADVANCE', 'Fantastic 4 (E)(Independent)', '2005', 'Action', 'Seven Studios', '2', 'Action Adventure', 'Isometric beat ''em up and action.', 'Defeat Doctor Doom and save New York City.', 'Team up as the Fantastic 4 to stop cosmic threats.', 'Fantastic 4 for GBA allows you to switch between Mr. Fantastic, Invisible Woman, The Thing, and Human Torch. Utilize their unique super-powers to solve puzzles and crush enemies in this movie-based brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantastic-4-erising-sun', 'GAMEBOYADVANCE', 'Fantastic 4 (E)(Rising Sun)', '2005', 'Action', 'Seven Studios', '2', 'Action Adventure', 'Isometric beat ''em up and action.', 'Defeat Doctor Doom and save New York City.', 'Team up as the Fantastic 4 to stop cosmic threats.', 'This European release features polished isometric combat. Experience the origin story of the Marvel team as you battle through 2D environments and upgrade your heroes'' iconic abilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantastic-4-iindependent', 'GAMEBOYADVANCE', 'Fantastic 4 (I)(Independent)', '2005', 'Action', 'Seven Studios', '2', 'Action Adventure', 'Isometric beat ''em up and action.', 'Defeat Doctor Doom and save New York City.', 'Team up as the Fantastic 4 to stop cosmic threats.', 'The Italian version of Fantastic 4 brings the blockbuster movie action to your pocket. Master the Thing''s strength and Sue Storm''s invisibility to navigate Dr. Doom''s treacherous traps.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantastic-4-urising-sun', 'GAMEBOYADVANCE', 'Fantastic 4 (U)(Rising Sun)', '2005', 'Action', 'Seven Studios', '2', 'Action Adventure', 'Isometric beat ''em up and action.', 'Defeat Doctor Doom and save New York City.', 'Team up as the Fantastic 4 to stop cosmic threats.', 'The US version of Fantastic 4 offers a solid cooperative-style brawling experience. Level up each member of the team to unlock devastating special attacks and defeat the world''s most dangerous villains.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantastic-children-jwrg', 'GAMEBOYADVANCE', 'Fantastic Children (J)(WRG)', '2004', 'RPG', 'Nippon Animation', '1', 'Japanese RPG', 'Turn-based RPG and adventure.', 'Solve the mystery of the "Fantastic Children" and their past.', 'A deep RPG based on the Japanese sci-fi anime.', 'Fantastic Children (Japan) features a rich narrative and strategic combat. Follow a group of mysterious children through time and space in this beautifully illustrated and story-driven handheld exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fear-factor---unleashed-urising-sun', 'GAMEBOYADVANCE', 'Fear Factor - Unleashed (U)(Rising Sun)', '2004', 'Action', 'Saffire', '1', 'Action Challenge', 'Mini-game collection and survival.', 'Complete gross-out stunts and fearsome challenges.', 'The official GBA game of the hit reality TV show.', 'Fear Factor - Unleashed features various "fear-based" mini-games. From eating insects to hanging from helicopters, test your timing and stomach in this digital adaptation of the extreme survival show.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('field-of-nine-digital-edition-2001-jeurasia', 'GAMEBOYADVANCE', 'Field of Nine Digital Edition 2001 (J)(Eurasia)', '2001', 'Board Game', 'Bottom Up', '2', 'Digital Board Game', 'Sports / Baseball Simulation.', 'Win the professional Japanese baseball league.', 'A detailed and technical digital baseball simulator.', 'Field of Nine Digital Edition 2001 features official players and teams from the Japanese league. Manage your pitching rotation and batting strategy in this deep and realistic sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-06-usupplex', 'GAMEBOYADVANCE', 'Fifa 06 (U)(Supplex)', '2005', 'Sports', 'EA Canada', '4', 'Soccer Simulation', 'Sports / Soccer Simulation.', 'Lead your favorite club to international glory.', 'A polished and feature-rich entry in the FIFA series.', 'FIFA 06 for GBA offers improved physics and a robust career mode. Choose from hundreds of licensed teams and experience the atmosphere of professional soccer with fluid animations and responsive controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-2003-umode7', 'GAMEBOYADVANCE', 'FIFA 2003 (U)(Mode7)', '2002', 'Sports', 'EA Canada', '4', 'Soccer Simulation', 'Sports / Soccer Simulation.', 'Lead your favorite club to international glory.', 'The debut of the FIFA franchise on the GBA.', 'FIFA 2003 brings the world''s game to your handheld. Featuring an isometric perspective and smooth passing mechanics, it’s a classic soccer experience with all the official licenses of the era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-2004-urising-sun', 'GAMEBOYADVANCE', 'FIFA 2004 (U)(Rising Sun)', '2003', 'Sports', 'EA Canada', '4', 'Soccer Simulation', 'Sports / Soccer Simulation.', 'Lead your favorite club to international glory.', 'The high-octane 2004 edition of the FIFA series.', 'FIFA 2004 introduces deeper tactical controls and improved AI. Compete in various leagues and tournaments, mastering the art of the free-kick in this polished portable sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-2005-uvenom', 'GAMEBOYADVANCE', 'FIFA 2005 (U)(Venom)', '2004', 'Sports', 'EA Canada', '4', 'Soccer Simulation', 'Sports / Soccer Simulation.', 'Lead your favorite club to international glory.', 'The 2005 edition of the legendary soccer franchise.', 'FIFA 2005 features refined ball physics and a more realistic pace. Manage your team''s formation and substitutions to dominate the pitch in this comprehensive handheld soccer simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-soccer-07-urising-sun', 'GAMEBOYADVANCE', 'FIFA Soccer 07 (U)(Rising Sun)', '2006', 'Sports', 'EA Canada', '4', 'Soccer Simulation', 'Sports / Soccer Simulation.', 'Lead your favorite club to international glory.', 'The final "numbered" FIFA title for the GBA.', 'FIFA Soccer 07 offers the most refined gameplay of the series on the system. With updated rosters and smooth framerates, it provides a high-quality soccer experience for fans on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-world-cup-2006-utrashman', 'GAMEBOYADVANCE', 'FIFA World Cup 2006 (U)(Trashman)', '2006', 'Sports', 'EA Canada', '4', 'Soccer Simulation', 'Sports / Soccer Simulation.', 'Win the FIFA World Cup trophy for your nation.', 'The official game of the 2006 World Cup in Germany.', 'FIFA World Cup 2006 features all the qualified national teams. Experience the tension of the world''s biggest tournament, from the group stages to the final showdown, with authentic stadiums and music.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fightbox-etrashman', 'GAMEBOYADVANCE', 'FightBox (E)(TrashMan)', '2005', 'Sports', 'Midway', '2', 'Boxing Arcade', 'Robot brawler and customization.', 'Build the ultimate warrior and win the FightBox.', 'Based on the BBC robot combat television series.', 'FightBox (Europe) allows you to design and upgrade your own digital fighter. Compete in various arena challenges and 1v1 battles to prove your creation is the strongest in the box.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fila-decathlon-evenom', 'GAMEBOYADVANCE', 'FILA Decathlon (E)(Venom)', '2003', 'Sports', 'KCEO', '4', 'Sports Compilation', 'Sports / Athletics Simulation.', 'Win the gold medal in the ten-event decathlon.', 'A challenging multi-event track and field simulator.', 'FILA Decathlon features events like the 100m sprint, long jump, and javelin. Master the timing and rhythm required for each specific discipline to become the ultimate track and field champion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-i-&-ii---dawn-of-souls-eindependent', 'GAMEBOYADVANCE', 'Final Fantasy I & II - Dawn of Souls (E)(Independent)', '2004', 'RPG', 'Square Enix', '1', 'Turn-Based RPG', 'Turn-based RPG (Remake).', 'Defeat Chaos and restore light to the crystals.', 'Two legendary RPG classics in one GBA cartridge.', 'Final Fantasy I & II - Dawn of Souls features updated graphics and new bonus dungeons. Experience the origins of the franchise with refined gameplay, featuring both the original quest and its direct sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-i-&-ii---dawn-of-souls-uindependent', 'GAMEBOYADVANCE', 'Final Fantasy I & II - Dawn of Souls (U)(Independent)', '2004', 'RPG', 'Square Enix', '1', 'Turn-Based RPG', 'Turn-based RPG (Remake).', 'Defeat Chaos and restore light to the crystals.', 'Two legendary RPG classics in one GBA cartridge.', 'The US version of Dawn of Souls includes the "Soul of Rebirth" scenario for FFII. Level up your party and master the job system in these two timeless masterpieces, optimized for handheld play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-i-&-ii-advance-jhyperion', 'GAMEBOYADVANCE', 'Final Fantasy I & II Advance (J)(Hyperion)', '2004', 'RPG', 'Square Enix', '1', 'Turn-Based RPG', 'Turn-based RPG (Remake).', 'Defeat Chaos and restore light to the crystals.', 'The Japanese version of the I & II compilation.', 'Final Fantasy I & II Advance brings the 8-bit classics into the 16-bit era with beautiful sprite work and rearranged soundtracks. A must-have for RPG purists and fans of the series'' history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-iv-advance-eeternity', 'GAMEBOYADVANCE', 'Final Fantasy IV Advance (E)(Eternity)', '2005', 'RPG', 'Square Enix', '1', 'Turn-Based RPG', 'Turn-based RPG (Remake).', 'Stop the sorcerer Golbez and save the Blue Planet.', 'An enhanced port of the epic story of Cecil and Kain.', 'Final Fantasy IV Advance features a revised translation and new endgame content. Follow the Dark Knight''s journey of redemption in one of the most beloved and dramatic RPG stories ever told.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-iv-advance-j2ch', 'GAMEBOYADVANCE', 'Final Fantasy IV Advance (J)(2CH)', '2005', 'RPG', 'Square Enix', '1', 'Turn-Based RPG', 'Turn-based RPG (Remake).', 'Stop the sorcerer Golbez and save the Blue Planet.', 'The original Japanese release of the FFIV GBA port.', 'FFIV Advance (Japan) delivers the classic Active Time Battle (ATB) system with portable convenience. Manage a rotating party of iconic heroes and traverse the world, underground, and moon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-iv-advance-jwrg', 'GAMEBOYADVANCE', 'Final Fantasy IV Advance (J)(WRG)', '2005', 'RPG', 'Square Enix', '1', 'Turn-Based RPG', 'Turn-based RPG (Remake).', 'Stop the sorcerer Golbez and save the Blue Planet.', 'The original Japanese release of the FFIV GBA port.', 'Experience the dramatic tale of Cecil Harvey in its Japanese GBA format. This version includes the Lunar Ruins dungeon and the ability to switch party members in the final act of the game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-iv-advance-uindependent', 'GAMEBOYADVANCE', 'Final Fantasy IV Advance (U)(Independent)', '2005', 'RPG', 'Square Enix', '1', 'Turn-Based RPG', 'Turn-based RPG (Remake).', 'Stop the sorcerer Golbez and save the Blue Planet.', 'The US version of the legendary FFIV adventure.', 'Final Fantasy IV Advance (US) is the definitive way to play this classic on the go. Experience the emotional plot and tactical battles, now with added character portraits and extra dungeons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-tactics-advance-esurplus', 'GAMEBOYADVANCE', 'Final Fantasy Tactics Advance (E)(Surplus)', '2003', 'Strategy RPG', 'Square Enix', '1', 'Tactical RPG', 'Tactical Turn-based RPG.', 'Navigate the world of Ivalice and find a way home.', 'A strategic spin-off with a deep "Law" system.', 'Final Fantasy Tactics Advance (Europe) features grid-based combat and a robust job system. Manage your clan and navigate the changing laws of the battlefield in this massive and addictive strategy RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-tactics-advance-jeurasia', 'GAMEBOYADVANCE', 'Final Fantasy Tactics Advance (J)(Eurasia)', '2003', 'Strategy RPG', 'Square Enix', '1', 'Tactical RPG', 'Tactical Turn-based RPG.', 'Navigate the world of Ivalice and find a way home.', 'The original Japanese release of the Tactics spin-off.', 'FFTA (Japan) brings the deep strategy of the Tactics series to a colorful new world. Customize your units with over 30 jobs and hundreds of abilities in this critically acclaimed title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-tactics-advance-ueurasia', 'GAMEBOYADVANCE', 'Final Fantasy Tactics Advance (U)(Eurasia)', '2003', 'Strategy RPG', 'Square Enix', '1', 'Tactical RPG', 'Tactical Turn-based RPG.', 'Navigate the world of Ivalice and find a way home.', 'The US version of the strategic Ivalice adventure.', 'Final Fantasy Tactics Advance (US) offers hundreds of hours of gameplay. Complete missions, recruit new races, and master the strategic depth of the "Judge" and "Law" mechanics on your GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-v-advance-eeternity', 'GAMEBOYADVANCE', 'Final Fantasy V Advance (E)(Eternity)', '2006', 'RPG', 'Square Enix', '1', 'Turn-Based RPG', 'Turn-based RPG (Remake).', 'Master the job system to stop the void from consuming reality.', 'The ultimate version of the series'' best job system.', 'Final Fantasy V Advance (Europe) features four new jobs (including Gladiator and Necromancer) and a bonus dungeon. Master the art of multi-classing in this deep and highly replayable RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-v-advance-jwrg', 'GAMEBOYADVANCE', 'Final Fantasy V Advance (J)(WRG)', '2006', 'RPG', 'Square Enix', '1', 'Turn-Based RPG', 'Turn-based RPG (Remake).', 'Master the job system to stop the void from consuming reality.', 'The original Japanese release of the FFV GBA port.', 'FFV Advance (Japan) showcases the perfection of the 2D job system. Mix and match abilities from dozens of classes to create the ultimate party and defeat the ancient evil, Exdeath.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-v-advance-uindependent', 'GAMEBOYADVANCE', 'Final Fantasy V Advance (U)(Independent)', '2006', 'RPG', 'Square Enix', '1', 'Turn-Based RPG', 'Turn-based RPG (Remake).', 'Master the job system to stop the void from consuming reality.', 'The US version of the definitive FFV experience.', 'Final Fantasy V Advance (US) features a brilliant translation and polished 2D graphics. Experiment with endless character builds and tackle the challenging Sealed Temple in this RPG fan favorite.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-vi-advance-eeternity', 'GAMEBOYADVANCE', 'Final Fantasy VI Advance (E)(Eternity)', '2007', 'RPG', 'Square Enix', '1', 'Turn-Based RPG', 'Turn-based RPG (Remake).', 'Lead the rebellion against the Gestahlian Empire.', 'Widely considered one of the greatest RPGs of all time.', 'Final Fantasy VI Advance (Europe) brings the epic story of Terra and Celes to the GBA. Featuring new Espers and a refined translation, it is the most complete version of this cinematic masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-vi-advance-jwrg', 'GAMEBOYADVANCE', 'Final Fantasy VI Advance (J)(WRG)', '2007', 'RPG', 'Square Enix', '1', 'Turn-Based RPG', 'Turn-based RPG (Remake).', 'Lead the rebellion against the Gestahlian Empire.', 'The original Japanese release of the FFVI GBA port.', 'Final Fantasy VI Advance (Japan) delivers the emotional weight and complex character arcs of the original with portable enhancements. Master the "Magicite" system and survive the World of Ruin.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-vi-advance-uxenophobia', 'GAMEBOYADVANCE', 'Final Fantasy VI Advance (U)(Xenophobia)', '2007', 'RPG', 'Square Enix', '1', 'Turn-Based RPG', 'Turn-based RPG (Remake).', 'Lead the rebellion against the Gestahlian Empire.', 'The US version of the landmark FFVI RPG.', 'Final Fantasy VI Advance (US) is a technical and narrative triumph. Experience the unforgettable soundtrack and deep tactical combat in this definitive handheld version of the 16-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fight-one-eparacox', 'GAMEBOYADVANCE', 'Final Fight One (E)(Paracox)', '2001', 'Action', 'Capcom', '2', 'Beat ''em up', 'Side-scrolling beat ''em up.', 'Rescue Jessica and clean up the streets of Metro City.', 'An enhanced GBA port of the arcade brawler classic.', 'Final Fight One features the original trio (Guy, Cody, Haggar) plus unlockable Alpha versions. Battle through Mad Gear gang territory in this definitive handheld version of the genre-defining brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fight-one-jeurasia', 'GAMEBOYADVANCE', 'Final Fight One (J)(Eurasia)', '2001', 'Action', 'Capcom', '2', 'Beat ''em up', 'Side-scrolling beat ''em up.', 'Rescue Jessica and clean up the streets of Metro City.', 'The original Japanese release of the GBA Final Fight.', 'Experience the uncensored Japanese version of Final Fight One. Featuring fluid animations and new dialogue scenes, it’s a perfect port of the high-octane 1989 arcade masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fight-one-umode7', 'GAMEBOYADVANCE', 'Final Fight One (U)(Mode7)', '2001', 'Action', 'Capcom', '2', 'Beat ''em up', 'Side-scrolling beat ''em up.', 'Rescue Jessica and clean up the streets of Metro City.', 'The US version of the definitive GBA brawler.', 'Final Fight One (US) brings arcade-quality action to the GBA. Master each character''s fighting style, use environmental weapons, and take down the infamous boss Rolento in this portable classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fire-pro-wrestling-jvenom', 'GAMEBOYADVANCE', 'Final Fire Pro Wrestling (J)(Venom)', '2001', 'Sports', 'Human Entertainment', '2', 'Pro Wrestling', 'Professional wrestling simulation.', 'Win the world championship and manage your wrestling career.', 'A deep and technical Japanese wrestling sim.', 'Final Fire Pro Wrestling (Japan) is known for its incredible customization. Create your own wrestler and master the timing-based grapple system in the most advanced entry of the series on GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('findet-nemo-gsuxxors', 'GAMEBOYADVANCE', 'Findet Nemo (G)(Suxxors)', '2003', 'Action', 'Traveller''s Tales', '1', 'Action Adventure', 'Side-scrolling adventure and mini-games.', 'Help Marlin and Dory find Nemo in the big ocean.', 'The German-localized edition of the Pixar hit.', 'Findet Nemo (Germany) follows the movie''s plot through a series of underwater levels. Navigate reefs and shipwrecks while avoiding sharks and jellyfish in this family-friendly adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('finding-nemo---arata-na-bouken-jcaravan', 'GAMEBOYADVANCE', 'Finding Nemo - Arata na Bouken (J)(Caravan)', '2003', 'Action', 'Traveller''s Tales', '1', 'Action Adventure', 'Side-scrolling adventure and mini-games.', 'Help Marlin and Dory find Nemo in the big ocean.', 'The Japanese version of the Pixar underwater quest.', 'Finding Nemo - Arata na Bouken features beautiful aquatic backgrounds and accessible gameplay. Relive the cinematic journey of the clownfish family on your GBA with localized Japanese text.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('finding-nemo---the-continuing-adventures-eindependent', 'GAMEBOYADVANCE', 'Finding Nemo - The Continuing Adventures (E)(Independent)', '2003', 'Action', 'Traveller''s Tales', '1', 'Action Adventure', 'Puzzle adventure and mini-games.', 'Complete various oceanic tasks after the movie''s events.', 'A sequel-style adventure featuring Nemo and friends.', 'Finding Nemo - The Continuing Adventures (Europe) offers new challenges beyond the film. Play as different characters from the tank gang in a variety of educational and skill-based mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('finding-nemo---the-continuing-adventures-erising-sun', 'GAMEBOYADVANCE', 'Finding Nemo - The Continuing Adventures (E)(Rising Sun)', '2003', 'Action', 'Traveller''s Tales', '1', 'Action Adventure', 'Puzzle adventure and mini-games.', 'Complete various oceanic tasks after the movie''s events.', 'A sequel-style adventure featuring Nemo and friends.', 'This European release focuses on fun and variety. Help the fish from the dentist''s office adjust to life in the ocean through dozens of engaging puzzles and timed challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('finding-nemo---the-continuing-adventures-uvenom', 'GAMEBOYADVANCE', 'Finding Nemo - The Continuing Adventures (U)(Venom)', '2003', 'Action', 'Traveller''s Tales', '1', 'Action Adventure', 'Puzzle adventure and mini-games.', 'Complete various oceanic tasks after the movie''s events.', 'The US version of the Nemo sequel mini-game pack.', 'Finding Nemo - The Continuing Adventures (US) is a perfect pick-up-and-play title for younger fans. Experience new story snippets and master 20+ mini-games featuring your favorite sea creatures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('finding-nemo-eindependent', 'GAMEBOYADVANCE', 'Finding Nemo (E)(Independent)', '2003', 'Action', 'Traveller''s Tales', '1', 'Action Adventure', 'Side-scrolling adventure and mini-games.', 'Help Marlin and Dory find Nemo in the big ocean.', 'The classic movie tie-in platformer and puzzle game.', 'Finding Nemo (Europe) captures the charm of the Pixar film. Control Marlin, Dory, and Nemo through 15+ levels of bubble-popping, shark-dodging, and turtle-riding action on the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('finding-nemo-epatience', 'GAMEBOYADVANCE', 'Finding Nemo (E)(Patience)', '2003', 'Action', 'Traveller''s Tales', '1', 'Action Adventure', 'Side-scrolling adventure and mini-games.', 'Help Marlin and Dory find Nemo in the big ocean.', 'The classic movie tie-in platformer and puzzle game.', 'Navigate the EAC and the Sydney harbor in this faithful adaptation. Finding Nemo provides a mix of exploration and light combat, making it an ideal handheld experience for fans of all ages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('finding-nemo-jrising-sun', 'GAMEBOYADVANCE', 'Finding Nemo (J)(Rising Sun)', '2003', 'Action', 'Traveller''s Tales', '1', 'Action Adventure', 'Side-scrolling adventure and mini-games.', 'Help Marlin and Dory find Nemo in the big ocean.', 'The Japanese version of the Pixar underwater quest.', 'Experience the magic of Nemo with localized Japanese support. Master the "Dory Speak" mini-games and escape the clutches of the divers in this polished and vibrant handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('finding-nemo-umode7', 'GAMEBOYADVANCE', 'Finding Nemo (U)(Mode7)', '2003', 'Action', 'Traveller''s Tales', '1', 'Action Adventure', 'Side-scrolling adventure and mini-games.', 'Help Marlin and Dory find Nemo in the big ocean.', 'The US version of the hit Pixar movie game.', 'Finding Nemo (US) features impressive water effects and cinematic stills from the movie. Lead the clownfish duo across the ocean in a quest filled with humor, danger, and friendship.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-emblem---rekka-no-ken-jgbatemp', 'GAMEBOYADVANCE', 'Fire Emblem - Rekka no Ken (J)(GBATemp)', '2003', 'Strategy RPG', 'Intelligent Systems', '1', 'Tactical RPG', 'Tactical Turn-based RPG.', 'Lead Eliwood and Hector to stop a global conspiracy.', 'The original Japanese release of the first Western FE.', 'Fire Emblem - Rekka no Ken (Blazing Blade) features a deep story and permadeath mechanics. Master the weapon triangle and grow your army in this tactical masterpiece that defined the genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-emblem---sealed-sword-binding-blade-utranslated', 'GAMEBOYADVANCE', 'Fire Emblem - Sealed Sword (Binding Blade) (U)(Translated)', '2002', 'Strategy RPG', 'Intelligent Systems', '1', 'Tactical RPG', 'Tactical Turn-based RPG.', 'Reclaim the kingdom of Pherae as young Roy.', 'The fan-translated version of the Japan-only hit.', 'Fire Emblem - Binding Blade (Sealed Sword) is the direct sequel to the first GBA game. Use this English patch to experience Roy''s epic journey through Elibe with full story and menu translation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-emblem---sealed-sword-jeurasia', 'GAMEBOYADVANCE', 'Fire Emblem - Sealed Sword (J)(Eurasia)', '2002', 'Strategy RPG', 'Intelligent Systems', '1', 'Tactical RPG', 'Tactical Turn-based RPG.', 'Reclaim the kingdom of Pherae as young Roy.', 'The original Japanese release starring Roy.', 'Fire Emblem - Fuuin no Tsurugi (Binding Blade) is a legendary challenge. Manage your units carefully across massive battlefields in the game that introduced Roy to the world before Super Smash Bros.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-emblem---seima-no-kouseki-jwrg', 'GAMEBOYADVANCE', 'Fire Emblem - Seima no Kouseki (J)(WRG)', '2004', 'Strategy RPG', 'Intelligent Systems', '1', 'Tactical RPG', 'Tactical Turn-based RPG.', 'Save the continent of Magvel from the Demon King.', 'The original Japanese release of the third GBA entry.', 'Fire Emblem - Seima no Kouseki (Sacred Stones) introduces a world map and branching promotions. Choose between Eirika or Ephraim''s path in this refined and accessible tactical RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-emblem---the-sacred-stones-erising-sun', 'GAMEBOYADVANCE', 'Fire Emblem - The Sacred Stones (E)(Rising Sun)', '2004', 'Strategy RPG', 'Intelligent Systems', '1', 'Tactical RPG', 'Tactical Turn-based RPG.', 'Save the continent of Magvel from the Demon King.', 'The European version of the Sacred Stones adventure.', 'Fire Emblem - The Sacred Stones (Europe) features the "Tower of Valni" for grinding levels. Master new classes and build the ultimate army to defeat the rising undead threat in Magvel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-emblem---the-sacred-stones-utrashman', 'GAMEBOYADVANCE', 'Fire Emblem - The Sacred Stones (U)(TrashMan)', '2004', 'Strategy RPG', 'Intelligent Systems', '1', 'Tactical RPG', 'Tactical Turn-based RPG.', 'Save the continent of Magvel from the Demon King.', 'The US version of the beloved tactical sequel.', 'Sacred Stones (US) offers a high-fantasy story and deep strategic combat. Experience the emotional bond between the royal twins and the traitorous Grado Empire in this GBA classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-emblem---the-sacred-trilogy-reskin-and-rebalance', 'GAMEBOYADVANCE', 'Fire Emblem - The Sacred Trilogy Reskin and Rebalance', '2005', 'Strategy RPG', 'Fan Hack', '1', 'Tactical RPG', 'Tactical Turn-based RPG (Hack).', 'Experience a fresh take on the Sacred Stones story.', 'A massive overhaul mod with new sprites and balance.', 'The Sacred Trilogy Reskin and Rebalance updates every unit, class, and map. Featuring modern quality-of-life features and beautiful new art, it’s the definitive way for veterans to replay Magvel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-emblem---the-sacred-war', 'GAMEBOYADVANCE', 'Fire Emblem - The Sacred War', '2005', 'Strategy RPG', 'Fan Hack', '1', 'Tactical RPG', 'Tactical Turn-based RPG (Hack).', 'Battle through new custom maps and story beats.', 'A fan-made expansion of the Fire Emblem mechanics.', 'Fire Emblem - The Sacred War increases the difficulty and adds custom units to the base game. Perfect for strategy fans looking for a more punishing and strategic experience on the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-emblem-eindependent', 'GAMEBOYADVANCE', 'Fire Emblem (E)(Independent)', '2003', 'Strategy RPG', 'Intelligent Systems', '1', 'Tactical RPG', 'Tactical Turn-based RPG.', 'Lead Eliwood and Hector to stop a global conspiracy.', 'The first Fire Emblem game released outside of Japan.', 'Known simply as "Fire Emblem" in the West, this game features a 10-chapter tutorial starring Lyn followed by a massive campaign. It is the gold standard for GBA tactical strategy games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-emblem-erising-sun', 'GAMEBOYADVANCE', 'Fire Emblem (E)(Rising Sun)', '2003', 'Strategy RPG', 'Intelligent Systems', '1', 'Tactical RPG', 'Tactical Turn-based RPG.', 'Lead Eliwood and Hector to stop a global conspiracy.', 'The European edition of the tactical classic.', 'This version of Fire Emblem features multiple difficulty modes and a deep support system between characters. Experience the epic lore of Elibe and the legendary weapons of the eight legends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-emblem-uvenom', 'GAMEBOYADVANCE', 'Fire Emblem (U)(Venom)', '2003', 'Strategy RPG', 'Intelligent Systems', '1', 'Tactical RPG', 'Tactical Turn-based RPG.', 'Lead Eliwood and Hector to stop a global conspiracy.', 'The US version of the landmark strategy RPG.', 'Fire Emblem (US) delivers a perfect blend of story and strategy. Manage resources, survive permadeath, and uncover the secret of the Dragons in this must-play GBA masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-pro-wrestling-umode7', 'GAMEBOYADVANCE', 'Fire Pro Wrestling (U)(Mode7)', '2001', 'Sports', 'Human Entertainment', '2', 'Pro Wrestling', 'Professional wrestling simulation.', 'Rise through the ranks and become a legend.', 'The Western debut of the hardcore wrestling sim.', 'Fire Pro Wrestling (US) features over 200 customizable wrestlers. With its focus on logic and timing rather than button mashing, it provides the most realistic wrestling experience on handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-pro-wrestling-2-uvenom', 'GAMEBOYADVANCE', 'Fire Pro Wrestling 2 (U)(Venom)', '2002', 'Sports', 'Human Entertainment', '2', 'Pro Wrestling', 'Professional wrestling simulation.', 'Manage your own promotion and win the belt.', 'The improved sequel with deeper management modes.', 'Fire Pro Wrestling 2 (US) adds an "Ironman" management mode and even more creation options. Execute hundreds of unique moves in this technical and highly-regarded wrestling sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-pro-wrestling-a-jcapital', 'GAMEBOYADVANCE', 'Fire Pro Wrestling A (J)(Capital)', '2004', 'Sports', 'Spike', '2', 'Pro Wrestling', 'Professional wrestling simulation.', 'Win the world championship and manage your career.', 'The original Japanese release of Fire Pro A.', 'Experience the foundation of GBA wrestling. Fire Pro Wrestling A (Japan) features the series'' signature sprite art and deep gameplay mechanics that made it a cult hit worldwide.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-sonic-revamped-in-sonic-battle', 'GAMEBOYADVANCE', 'Fire Sonic Revamped In Sonic Battle', '2004', 'Action', 'Fan Hack', '1', 'Platform Hack', '2D Arena Fighting (Hack).', 'Play as a revamped Fire Sonic in combat arenas.', 'A character overhaul mod for Sonic Battle.', 'Fire Sonic Revamped brings an elemental twist to the fighting game. Featuring custom fire-based animations and modified special moves, it adds a hot new dynamic to the original Sonic Battle roster.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flame-of-recca-jeurasia', 'GAMEBOYADVANCE', 'Flame of Recca (J)(Eurasia)', '2004', 'Action', 'Konami', '1', 'Action Adventure', '2D Fighting game.', 'Win the tournament using powerful fire-casting.', 'A Japanese fighter based on the popular manga.', 'Flame of Recca features fast-paced martial arts and mystical flame powers. Master the unique "Hokage" abilities and battle through the story mode in this stylish and technical Japanese fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fleetway-sonic', 'GAMEBOYADVANCE', 'Fleetway Sonic', '2005', 'Action', 'Fan Hack', '1', 'Platform Hack', '2D Arena Fighting (Hack).', 'Fight as the Fleetway comics version of Sonic.', 'A character replacement mod for Sonic Battle.', 'Fleetway Sonic brings the aggressive and edgy version of the hedgehog to the arena. Featuring custom sprites based on the UK comic series, it offers a fresh visual style for Sonic fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fleetway-super-shadow', 'GAMEBOYADVANCE', 'Fleetway Super Shadow', '2005', 'Action', 'Fan Hack', '1', 'Platform Hack', '2D Arena Fighting (Hack).', 'Unleash the power of Fleetway Super Shadow.', 'A powerful character mod for Sonic Battle.', 'This mod introduces a high-powered, stylized version of Super Shadow. With custom palettes and modified hitboxes, it turns the ultimate lifeform into a comic-book powerhouse.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fleetway-super-sonic', 'GAMEBOYADVANCE', 'Fleetway Super Sonic', '2005', 'Action', 'Fan Hack', '1', 'Platform Hack', '2D Arena Fighting (Hack).', 'Survive the chaos of the Fleetway Super Sonic form.', 'A character overhaul featuring the psychotic Super Sonic.', 'Fleetway Super Sonic brings the terrifying and powerful transformation from the Fleetway comics to Sonic Battle. Use devastating energy attacks and aggressive combos in this unique fan mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flushed-away-erising-sun', 'GAMEBOYADVANCE', 'Flushed Away (E)(Rising Sun)', '2006', 'Action Adventure', 'Amaze Entertainment', '1', 'Platform Adventure', 'Side-scrolling platformer.', 'Help Roddy and Rita escape the sewers of Ratropolis.', 'A fun adventure based on the Aardman/Dreamworks film.', 'Flushed Away (Europe) features a mix of platforming and boat-racing levels. Switch between Roddy and Rita to use their unique skills and navigate the dangerous London sewers in this charming movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flushed-away-urising-sun', 'GAMEBOYADVANCE', 'Flushed Away (U)(Rising Sun)', '2006', 'Action Adventure', 'Amaze Entertainment', '1', 'Platform Adventure', 'Side-scrolling platformer.', 'Help Roddy and Rita escape the sewers of Ratropolis.', 'A fun adventure based on the Aardman/Dreamworks film.', 'The US version of Flushed Away brings the witty humor of the movie to GBA. Master the "slapstick" combat and solve environmental puzzles to thwart the evil Toad''s plans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ford-racing-3-esupplex', 'GAMEBOYADVANCE', 'Ford Racing 3 (E)(sUppLeX)', '2005', 'Racing', 'Razorworks', '4', 'Arcade Racing', 'Arcade racing simulation.', 'Win championships to unlock iconic Ford vehicles.', 'A high-speed racer featuring a massive Ford catalog.', 'Ford Racing 3 (Europe) lets you drive everything from classic 1920s models to modern off-road trucks. Compete across 14 diverse tracks with realistic handling and impressive vehicle models for the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ford-racing-3-utrashman', 'GAMEBOYADVANCE', 'Ford Racing 3 (U)(Trashman)', '2005', 'Racing', 'Razorworks', '4', 'Arcade Racing', 'Arcade racing simulation.', 'Win championships to unlock iconic Ford vehicles.', 'A high-speed racer featuring a massive Ford catalog.', 'The US version of Ford Racing 3 offers intense competition. Unlock and customize iconic cars like the Mustang and GT while mastering the racing line on paved and off-road circuits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('formation-soccer-2002-jrapid-fire', 'GAMEBOYADVANCE', 'Formation Soccer 2002 (J)(Rapid Fire)', '2002', 'Sports', 'SCEI', '2', 'Soccer', 'Soccer simulation.', 'Win the world tournament with strategic plays.', 'A fast-paced and technical Japanese soccer game.', 'Formation Soccer 2002 features deep tactical management and smooth 2D gameplay. Adjust your formation in real-time and execute precision passes to dominate the pitch in this Japanese sports classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fortress-ewc', 'GAMEBOYADVANCE', 'Fortress (E)(wC)', '2001', 'Strategy', 'Rage Software', '1', 'Turn-Based Strategy', 'Strategy / Tower Defense.', 'Build a fortress to defend against enemy waves.', 'A creative mix of strategy and puzzle-solving.', 'Fortress (Europe) challenges you to balance offensive and defensive structures. Compete against AI or friends in a race to build the strongest tower while sabotaging your opponent''s construction.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fortress-ueurasia', 'GAMEBOYADVANCE', 'Fortress (U)(Eurasia)', '2001', 'Strategy', 'Rage Software', '1', 'Turn-Based Strategy', 'Strategy / Tower Defense.', 'Build a fortress to defend against enemy waves.', 'A creative mix of strategy and puzzle-solving.', 'The US version of Fortress features multiple themed worlds, from prehistoric to sci-fi. Use resource management and quick reflexes to protect your core from constant enemy bombardment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fosters-home-for-imaginary-friends-eindependent', 'GAMEBOYADVANCE', 'Foster''s Home for Imaginary Friends (E)(Independent)', '2006', 'Action Adventure', 'Behaviour Interactive', '1', 'Platform Adventure', 'Side-scrolling adventure.', 'Help Mac and Bloo find the hidden imaginary friends.', 'A whimsical quest based on the Cartoon Network show.', 'Foster''s Home for Imaginary Friends (Europe) captures the unique art style of the show. Navigate the mansion and use Bloo’s antics to solve puzzles and collect every imaginary friend.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fosters-home-for-imaginary-friends-urising-sun', 'GAMEBOYADVANCE', 'Foster''s Home for Imaginary Friends (U)(Rising Sun)', '2006', 'Action Adventure', 'Behaviour Interactive', '1', 'Platform Adventure', 'Side-scrolling adventure.', 'Help Mac and Bloo find the hidden imaginary friends.', 'A whimsical quest based on the Cartoon Network show.', 'The US version of Foster''s Home features fun platforming and light adventure elements. Explore the diverse rooms of the mansion and interact with iconic characters like Wilt, Eduardo, and Coco.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('franklin-the-turtle-ecezar', 'GAMEBOYADVANCE', 'Franklin the Turtle (E)(Cezar)', '2001', 'Educational', 'Shin''en Multimedia', '1', 'Educational Adventure', 'Educational adventure.', 'Solve puzzles and help friends around the village.', 'A gentle and colorful adventure for young children.', 'Franklin the Turtle (Europe) features mini-games focused on logic and friendship. Guide Franklin through the forest as he learns valuable life lessons through simple, engaging tasks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('franklin-the-turtle-utrashman', 'GAMEBOYADVANCE', 'Franklin The Turtle (U)(Trashman)', '2001', 'Educational', 'Shin''en Multimedia', '1', 'Educational Adventure', 'Educational adventure.', 'Solve puzzles and help friends around the village.', 'A gentle and colorful adventure for young children.', 'The US version of Franklin the Turtle provides an accessible and educational experience. Perfect for early gamers, it offers bright graphics and slow-paced gameplay designed for learning.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('franklins-great-adventure-erising-sun', 'GAMEBOYADVANCE', 'Franklin''s Great Adventure (E)(Rising Sun)', '2004', 'Adventure', 'Shin''en Multimedia', '1', 'Story Adventure', 'Adventure / Mini-games.', 'Complete a series of forest quests with Franklin.', 'An expanded adventure featuring the famous turtle.', 'Franklin''s Great Adventure (Europe) adds more variety to the mini-games. Participate in races, memory challenges, and puzzle-solving missions to help Franklin''s friends across the pond.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('franklins-great-adventures-utrashman', 'GAMEBOYADVANCE', 'Franklin''s Great Adventures (U)(Trashman)', '2004', 'Adventure', 'Shin''en Multimedia', '1', 'Story Adventure', 'Adventure / Mini-games.', 'Complete a series of forest quests with Franklin.', 'An expanded adventure featuring the famous turtle.', 'The US version of Franklin''s Great Adventures is a collection of heartwarming stories and games. Explore vibrant woodland environments and foster a love for nature and teamwork on your GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('freekstyle-erising-sun', 'GAMEBOYADVANCE', 'Freekstyle (E)(Rising Sun)', '2002', 'Sports', 'EA Sports Big', '2', 'Extreme Sports', 'Motocross / Stunt Racing.', 'Win races by performing insane, gravity-defying tricks.', 'An extreme freestyle motocross racer by EA Sports.', 'Freekstyle (Europe) features high-flying action and a deep trick system. Master the "Freek-out" meter to gain speed boosts and dominate the professional dirt-bike circuit with a cast of colorful riders.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('freekstyle-umode7', 'GAMEBOYADVANCE', 'Freekstyle (U)(Mode7)', '2002', 'Sports', 'EA Sports Big', '2', 'Extreme Sports', 'Motocross / Stunt Racing.', 'Win races by performing insane, gravity-defying tricks.', 'An extreme freestyle motocross racer by EA Sports.', 'The US version of Freekstyle brings the console energy to handheld. Combine backflips and tsunamis across treacherous terrain to prove you are the king of freestyle motocross.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('freestyle-scooter-egbatemp', 'GAMEBOYADVANCE', 'Freestyle Scooter (E)(GBATemp)', '2001', 'Sports', 'Shin''en Multimedia', '2', 'Extreme Sports', 'Extreme sports simulation.', 'Master the scooter and complete urban challenges.', 'A "Tony Hawk" style game focused on scooters.', 'Freestyle Scooter (Europe) features several pro riders and real-world skate parks. Grinds, bar-spins, and tail-whips are essential to scoring high and unlocking new gear in this unique sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('frogger-advance---the-great-quest-elightforce', 'GAMEBOYADVANCE', 'Frogger Advance - The Great Quest (E)(LightForce)', '2002', 'Action Adventure', 'Krome Studios', '1', '3D Platformer', '2D Action Platformer.', 'Navigate dangerous worlds to save the Frog Queen.', 'A story-driven adventure for the legendary frog.', 'Frogger Advance: The Great Quest (Europe) features expanded moves like double jumping and gliding. Help Frogger navigate swampy lands and castles in his quest to become a true hero.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('frogger-advance---the-great-quest-umode7', 'GAMEBOYADVANCE', 'Frogger Advance - The Great Quest (U)(Mode7)', '2002', 'Action Adventure', 'Krome Studios', '1', '3D Platformer', '2D Action Platformer.', 'Navigate dangerous worlds to save the Frog Queen.', 'A story-driven adventure for the legendary frog.', 'The US version of The Great Quest offers a modern take on the classic arcade formula. Solve environmental puzzles and defeat enemies in a vibrant 2D world inspired by fairy tales.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('frogger-kodaibunmei-no-nazo-jrising-sun', 'GAMEBOYADVANCE', 'Frogger Kodaibunmei no Nazo (J)(Rising Sun)', '2000', 'Action', 'Konami', '1', 'Action Platformer', 'Puzzle Platformer.', 'Solve the mysteries of ancient ruins as Frogger.', 'A classic adventure with a focus on puzzle-solving.', 'Frogger Kodaibunmei no Nazo (Ancient Civilization) features grid-based movement and clever level design. Avoid traps and enemies in exotic locations while searching for legendary relics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('frogger-mahou-no-kuni-no-daibouken-jrising-sun', 'GAMEBOYADVANCE', 'Frogger Mahou No Kuni No Daibouken (J)(Rising Sun)', '2001', 'Action', 'Konami', '1', 'Action Platformer', 'Adventure / Mini-games.', 'Journey through a magical land to save the kingdom.', 'A whimsical Frogger adventure with magical elements.', 'Frogger Mahou No Kuni (Land of Magic) mixes traditional "crossing" gameplay with new abilities. Explore a fantasy world filled with colorful characters and challenging boss encounters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('froggers-adventure-2---the-lost-wand-umode7', 'GAMEBOYADVANCE', 'Frogger''s Adventure 2 - The Lost Wand (U)(Mode7)', '2002', 'Action Adventure', 'Konami', '1', 'Platform Adventure', 'Isometric Adventure.', 'Find the Lost Wand to restore peace to Firefly Swamp.', 'The high-quality sequel to Frogger''s first GBA outing.', 'Frogger''s Adventure 2 (US) features impressive isometric graphics and diverse levels. Master the art of hopping across moving platforms and outsmarting predators in this polished sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('froggers-adventures---temple-of-the-frog-eindependent', 'GAMEBOYADVANCE', 'Frogger''s Adventures - Temple of the Frog (E)(Independent)', '2001', 'Action Adventure', 'Konami', '1', 'Action Adventure', 'Isometric Adventure.', 'Defeat the evil Mr. D and reclaim the sacred elements.', 'Frogger''s debut into the world of action-adventure.', 'Frogger''s Adventures: Temple of the Frog (Europe) features over 15 levels of strategic platforming. Use your long tongue and quick hops to navigate dangerous temples and rescue your friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('froggers-adventures---temple-of-the-frog-ulightforce', 'GAMEBOYADVANCE', 'Frogger''s Adventures - Temple of the Frog (U)(Lightforce)', '2001', 'Action Adventure', 'Konami', '1', 'Action Adventure', 'Isometric Adventure.', 'Defeat the evil Mr. D and reclaim the sacred elements.', 'Frogger''s debut into the world of action-adventure.', 'The US version of Temple of the Frog is a fan favorite for its balanced difficulty and charming art style. Collect every coin and secret item across various biomes to unlock hidden challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('froggers-adventures-2---the-lost-wand-erising-sun', 'GAMEBOYADVANCE', 'Frogger''s Adventures 2 - The Lost Wand (E)(Rising Sun)', '2002', 'Action Adventure', 'Konami', '1', 'Platform Adventure', 'Isometric Adventure.', 'Find the Lost Wand to restore peace to Firefly Swamp.', 'The European version of the acclaimed sequel.', 'Frogger''s Adventure 2 (Europe) offers more complex puzzles and varied mechanics. Explore ice worlds, volcanoes, and more in a quest that respects the character''s arcade roots.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('froggers-journey---the-forgotten-relic-umode7', 'GAMEBOYADVANCE', 'Frogger''s Journey - The Forgotten Relic (U)(Mode7)', '2003', 'Action Adventure', 'Konami', '1', 'Action Adventure', 'Adventure / RPG lite.', 'Search for a forgotten relic to save your village.', 'A story-heavy adventure with character progression.', 'Frogger''s Journey: The Forgotten Relic (US) adds an inventory system and NPC interactions. Experience a deeper narrative as you guide Frogger through 2D levels and master new survival skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('frontier-stories-jwrg', 'GAMEBOYADVANCE', 'Frontier Stories (J)(WRG)', '2001', 'RPG', 'Taito', '1', 'Life Simulation', 'Simulation / Strategy.', 'Build your settlement and manage resources in a new land.', 'A Japanese-exclusive life and strategy sim.', 'Frontier Stories (Japan) combines city-building elements with light RPG combat. Interact with settlers, manage crops, and defend your village in this charming and relaxing handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fruits-mura-no-doubutsu-tachi-jrising-sun', 'GAMEBOYADVANCE', 'Fruits Mura no Doubutsu Tachi (J)(Rising Sun)', '2002', 'Simulation', 'Nintendo', '1', 'Life Simulation', 'Social simulation.', 'Live and interact with animal friends in a fruit village.', 'A cute and colorful Japanese life simulator.', 'Fruits Mura features seasonal events and daily activities. Build friendships with diverse animal characters and customize your home in this "Animal Crossing" style GBA experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('full-metal-alchemist-jcezar', 'GAMEBOYADVANCE', 'Full Metal Alchemist (J)(Cezar)', '2003', 'Action RPG', 'Square Enix', '1', 'Action RPG', 'Tactical Action RPG.', 'Use alchemy to find the Philosopher''s Stone.', 'An intense adventure based on the FMA anime.', 'Fullmetal Alchemist (Japan) features Edward and Alphonse Elric. Use transmutation circles to create weapons and objects, engaging in strategic combat to follow the emotional story of the brothers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fushigi-no-kuni-no-alice-j2ch', 'GAMEBOYADVANCE', 'Fushigi no Kuni no Alice (J)(2CH)', '2001', 'Adventure', 'Marvelous Interactive', '1', 'Visual Novel', 'Adventure / Visual Novel.', 'Navigate Wonderland and meet its strange inhabitants.', 'A faithful Japanese adaptation of Lewis Carroll''s book.', 'Fushigi no Kuni no Alice (Alice in Wonderland) features beautiful illustrations and multiple choice-driven paths. Experience the surreal world of Wonderland in this polished Japanese handheld adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fushigi-no-kuni-no-angelique-jindependent', 'GAMEBOYADVANCE', 'Fushigi no Kuni no Angelique (J)(Independent)', '2002', 'Simulation', 'Koei', '1', 'Dating Simulation', 'Strategy / Otome simulation.', 'Become the Queen Candidate and gain the support of Guardians.', 'A popular Japanese social and strategy series.', 'Fushigi no Kuni no Angelique features romantic subplots and resource management. Interact with the nine Guardians to build your influence and decide the future of the cosmos.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('futari-ha-precure-arienaai-yume-no-kuni-ha-daimeikyuu-jcaravan', 'GAMEBOYADVANCE', 'Futari ha Precure Arienaai Yume no Kuni ha Daimeikyuu (J)(Caravan)', '2004', 'Action', 'Toei Animation', '1', 'Action Adventure', '2D Action Platformer.', 'Defeat the Dark Zone and protect the dream world.', 'A high-energy brawler based on the Pretty Cure anime.', 'Futari ha Precure features tag-team combat between Cure Black and Cure White. Master powerful combination attacks and platform through vibrant stages in this Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('futari-wa-precure-max-heart---maji-maji!-fight-de-in-janai-jsupplex', 'GAMEBOYADVANCE', 'Futari wa Precure Max Heart - Maji Maji! Fight de IN Janai (J)(Supplex)', '2005', 'Action', 'Fanworks', '1', 'Action Adventure', '2D Action Platformer.', 'Battle the forces of darkness with enhanced powers.', 'The action-packed sequel featuring the Max Heart cast.', 'Precure Max Heart features improved combat mechanics and new special moves. Help the magical girls protect the light through intense fighting stages and beautiful animated sequences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gachasta!-dino-device-2-dragon-jcezar', 'GAMEBOYADVANCE', 'Gachasta! Dino Device 2 Dragon (J)(Cezar)', '2003', 'Action', 'Takara', '1', 'Action Figures', 'Monster-battling RPG.', 'Collect, fuse, and battle robotic dinosaurs.', 'A unique creature-collecting RPG with a mechanical twist.', 'Gachasta! Dino Device 2 Dragon features strategic turn-based combat. Collect parts to upgrade your mechanical dinosaurs and compete in the Dragon League in this deep Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gachasta!-dino-device-2-phoenix-jcezar', 'GAMEBOYADVANCE', 'Gachasta! Dino Device 2 Phoenix (J)(Cezar)', '2003', 'Action', 'Takara', '1', 'Action Figures', 'Monster-battling RPG.', 'Collect, fuse, and battle robotic dinosaurs.', 'The Phoenix version of the robot-dino battling sequel.', 'This Phoenix edition of Dino Device 2 offers exclusive parts and different elemental strengths. Master the "Gacha" summoning system to build a legendary team of mechanical beasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gachasute!-dyna-device-blue-jchakky', 'GAMEBOYADVANCE', 'Gachasute! Dyna Device Blue (J)(Chakky)', '2002', 'Action', 'Takara', '1', 'Action Figures', 'Monster-battling RPG.', 'Collect and battle mechanical "Dyna" units.', 'The "Blue" edition of the Dyna Device series.', 'Gachasute! Dyna Device Blue focus on strategic robot battles. Customization is key, as players must balance power and agility to win the high-stakes Gacha tournaments in Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gachasute!-dyna-device-red-jindependent', 'GAMEBOYADVANCE', 'Gachasute! Dyna Device Red (J)(Independent)', '2002', 'Action', 'Takara', '1', 'Action Figures', 'Monster-battling RPG.', 'Collect and battle mechanical "Dyna" units.', 'The "Red" edition of the Dyna Device series.', 'Dyna Device Red features unique mechanical warriors not found in the Blue version. Trade parts and engage in tactical 1v1 battles to become the ultimate Dyna Master.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gachinko-pro-yakyuu-jchakky', 'GAMEBOYADVANCE', 'Gachinko Pro Yakyuu (J)(Chakky)', '2002', 'Sports', 'Konami', '2', 'Baseball Simulation', 'Sports / Baseball.', 'Lead your high-school team to victory in the Koshien.', 'A realistic and intense Japanese baseball simulation.', 'Gachinko Pro Yakyuu offers a deep "Success" mode where you train players from rookies to pros. Master the pitching and batting mechanics in this authentic Japanese sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gadget-racers-eindependent', 'GAMEBOYADVANCE', 'Gadget Racers (E)(Independent)', '2004', 'Racing', 'Crawfish Interactive', '4', 'Arcade Racing', 'Racing / Car Combat.', 'Win races and customize your car with over 100 gadgets.', 'A wacky and fast-paced racer (Choro Q series).', 'Gadget Racers (Europe) allows you to equip your car with wings, propellers, and weapons. Navigate creative tracks and outsmart rivals in this highly customizable arcade racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gadget-racers-ueurasia', 'GAMEBOYADVANCE', 'Gadget Racers (U)(Eurasia)', '2004', 'Racing', 'Crawfish Interactive', '4', 'Arcade Racing', 'Racing / Car Combat.', 'Win races and customize your car with over 100 gadgets.', 'A wacky and fast-paced racer (Choro Q series).', 'The US version of Gadget Racers features deep RPG-lite elements. Earn money from races to buy massive tires, powerful engines, and goofy gadgets to conquer all terrains.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gakkou-no-kaidan---hyakuyobako-no-fuuin-jcaravan', 'GAMEBOYADVANCE', 'Gakkou no Kaidan - Hyakuyobako no Fuuin (J)(Caravan)', '2002', 'Adventure', 'AlphaDream', '1', 'Horror Adventure', 'Horror / Visual Novel.', 'Seal the spirits of the hundred-story haunted school.', 'A spooky adventure based on Japanese urban legends.', 'Gakkou no Kaidan features a tense atmosphere and puzzle-solving. Use spiritual tools to banish ghosts and uncover the secrets of the school''s seal in this Japanese classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gakkou-o-tsukurou!!-advance-jcezar', 'GAMEBOYADVANCE', 'Gakkou o Tsukurou!! Advance (J)(Cezar)', '2001', 'Simulation', 'Enix', '1', 'School Management', 'Simulation / Management.', 'Build and manage your own dream school.', 'A detailed school administration simulator for GBA.', 'Gakkou o Tsukurou!! Advance lets you design classrooms, hire teachers, and manage student happiness. Watch your school grow from a small building into a world-class institution.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gakuen-alice---dokidoki-fushigi-taiken-jcaravan', 'GAMEBOYADVANCE', 'Gakuen Alice - DokiDoki Fushigi Taiken (J)(Caravan)', '2003', 'Adventure', 'Konami', '1', 'Story Adventure', 'Social Adventure.', 'Explore Alice Academy and make friends with students.', 'A charming adventure based on the Gakuen Alice manga.', 'Gakuen Alice: DokiDoki Fushigi Taiken features mini-games based on "Alices" (superpowers). Interact with Mikan and Natsume in a story-driven experience for fans of the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gakuen-senki-muryou-jrising-sun', 'GAMEBOYADVANCE', 'Gakuen Senki Muryou (J)(Rising Sun)', '2001', 'Strategy', 'Media Factory', '1', 'Tactical Strategy', 'Tactical Action RPG.', 'Protect Earth from alien threats with high-tech suits.', 'An action-adventure based on the sci-fi anime.', 'Gakuen Senki Muryou features strategic planning and real-time combat. Balance school life with galactic defense in this unique and polished Japanese handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('galaxy-angel-jchakky', 'GAMEBOYADVANCE', 'Galaxy Angel (J)(Chakky)', '2001', 'Strategy', 'Broccoli', '1', 'Turn-Based Strategy', 'Tactical RPG / Simulation.', 'Lead the Angel Brigade in space battles.', 'A strategy-sim based on the popular Galaxy Angel series.', 'Galaxy Angel for GBA features ship management and character interaction. Strengthen bonds with your crew to improve performance in tactical space combat missions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('galidor---defenders-of-the-outer-dimension-uvenom', 'GAMEBOYADVANCE', 'Galidor - Defenders of the Outer Dimension (U)(Venom)', '2002', 'Action', 'Amaze Entertainment', '1', 'Action Adventure', '3D-style Action Platformer.', 'Defeat Gorm and protect the Outer Dimension.', 'A sci-fi adventure based on the LEGO-inspired show.', 'Galidor: Defenders of the Outer Dimension features Nick Bluetooth''s "glinching" power. Shape-shift into different creatures to solve puzzles and defeat enemies in this unique 3D-styled GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('game-&-watch-gallery-4-uevlstar', 'GAMEBOYADVANCE', 'Game & Watch Gallery 4 (U)(Evlstar)', '2002', 'Miscellaneous', 'Nintendo', '2', 'Mini-Game Collection', 'Arcade / Minigame Collection.', 'Earn high scores in updated Nintendo classics.', 'A massive collection of Game & Watch handheld hits.', 'Game & Watch Gallery 4 features both "Classic" and "Modern" versions of games like Donkey Kong, Mario''s Cement Factory, and Fire. Unlock dozens of secrets in this ultimate nostalgia trip.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('game-&-watch-gallery-advance-emenace', 'GAMEBOYADVANCE', 'Game & Watch Gallery Advance (E)(Menace)', '2003', 'Miscellaneous', 'Nintendo', '2', 'Mini-Game Collection', 'Arcade / Minigame Collection.', 'Earn high scores in updated Nintendo classics.', 'The European edition of the Game & Watch compilation.', 'Experience the history of Nintendo''s first handhelds. This collection features polished GBA graphics for the modern modes while keeping the original 4-bit gameplay intact for purists.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gameboy-wars-advance-1+2-jcaravan', 'GAMEBOYADVANCE', 'Gameboy Wars Advance 1+2 (J)(Caravan)', '2004', 'Strategy', 'Nintendo', '2', 'Turn-Based Strategy', 'Turn-based Strategy.', 'Lead your army to victory in the Wars world.', 'A Japanese 2-in-1 pack of Advance Wars 1 and 2.', 'Gameboy Wars Advance 1+2 bundles the two best strategy games on the system. Command tanks, planes, and infantry with specialized CO powers in this definitive tactical compilation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('games-explosion!-urising-sun', 'GAMEBOYADVANCE', 'Games Explosion! (U)(Rising Sun)', '2003', 'Miscellaneous', 'Majesco', '4', 'Party Games', 'Puzzle / Mini-game Collection.', 'Master over 100 different arcade-style games.', 'A massive variety pack of quick-play titles.', 'Games Explosion! for GBA is perfect for short sessions. From logic puzzles to action challenges, it offers a huge library of simple but addictive games for players of all ages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ganbare-dodge-fighters-jrisingcaravan', 'GAMEBOYADVANCE', 'Ganbare Dodge Fighters (J)(RisingCaravan)', '2001', 'Sports', 'Compile', '4', 'Dodgeball', 'Sports / Dodgeball.', 'Win the dodgeball tournament with special attacks.', 'A high-energy Japanese dodgeball action game.', 'Ganbare Dodge Fighters features RPG-style progression and cinematic special moves. Build your team and master the timing of your throws to knock out the competition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('garfield---the-search-for-pooky-erising-sun', 'GAMEBOYADVANCE', 'Garfield - The Search For Pooky (E)(Rising Sun)', '2004', 'Platformer', 'Eko Software', '1', 'Cartoon Platformer', '2D Side-scrolling Platformer.', 'Find Jon and Odie to rescue Pooky the bear.', 'A colorful adventure starring the world''s laziest cat.', 'Garfield: The Search For Pooky (Europe) features classic platforming. Explore the house and neighborhood, collecting lasagna and avoiding pesky dogs in this faithful comic-strip adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('garfield---the-search-for-pooky-utrashman', 'GAMEBOYADVANCE', 'Garfield - The Search For Pooky (U)(Trashman)', '2004', 'Platformer', 'Eko Software', '1', 'Cartoon Platformer', '2D Side-scrolling Platformer.', 'Find Jon and Odie to rescue Pooky the bear.', 'A colorful adventure starring the world''s laziest cat.', 'The US version of Search For Pooky offers charming animations and accessible difficulty. Help Garfield navigate through various levels to recover his favorite teddy bear.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('garfield-and-his-nine-lives-elightforce', 'GAMEBOYADVANCE', 'Garfield and his Nine Lives (E)(LightForce)', '2004', 'Platformer', 'Victory Interactive', '1', 'Cartoon Platformer', '2D Side-scrolling Platformer.', 'Navigate through nine different "lives" or worlds.', 'An adventure based on the Garfield movie and comics.', 'Garfield and his Nine Lives (Europe) features diverse level themes, from a spooky graveyard to a high-tech lab. Use Garfield''s weight and claws to overcome obstacles and enemies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('garfield-and-his-nine-lives-utrashman', 'GAMEBOYADVANCE', 'Garfield and His Nine Lives (U)(Trashman)', '2004', 'Platformer', 'Victory Interactive', '1', 'Cartoon Platformer', '2D Side-scrolling Platformer.', 'Navigate through nine different "lives" or worlds.', 'An adventure based on the Garfield movie and comics.', 'The US version of Nine Lives delivers polished platforming and vibrant graphics. Each "life" offers a unique gameplay twist, providing a fresh experience across the entire game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gauntlet---dark-legacy-umode7', 'GAMEBOYADVANCE', 'Gauntlet - Dark Legacy (U)(Mode7)', '2002', 'Action', 'Midway Games', '4', 'Action RPG', 'Isometric Hack-and-Slash.', 'Defeat Garm and cleanse the four realms.', 'A portable port of the legendary arcade dungeon crawler.', 'Gauntlet: Dark Legacy features four classic classes: Warrior, Valkyrie, Wizard, and Archer. Battle through hordes of enemies, collect gold, and find the ancient shards to save the kingdom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gauntlet-&-rampart-esupplex', 'GAMEBOYADVANCE', 'Gauntlet & Rampart (E)(Supplex)', '2001', 'Action', 'Midway Games', '4', 'Arcade Action', 'Arcade Collection.', 'Survive the dungeon and defend the castle.', 'A 2-in-1 pack of two legendary Midway arcade hits.', 'Gauntlet & Rampart bundles the original dungeon-crawling Gauntlet with the strategic castle-building of Rampart. Experience two different styles of retro arcade action in one cartridge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gauntlet-&-rampart-utrashman', 'GAMEBOYADVANCE', 'Gauntlet & Rampart (U)(Trashman)', '2001', 'Action', 'Midway Games', '4', 'Arcade Action', 'Arcade Collection.', 'Survive the dungeon and defend the castle.', 'A 2-in-1 pack of two legendary Midway arcade hits.', 'The US version of this compilation offers perfect arcade ports for the GBA. Team up with a friend via link cable for the ultimate Gauntlet experience or test your speed in Rampart.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gba-tv-tuner-cindependent', 'GAMEBOYADVANCE', 'GBA TV Tuner (C)(Independent)', '2004', 'Hardware', 'Nintendo', '1', 'TV Accessory', 'Utility / Hardware Support.', 'Watch broadcast television on your Game Boy Advance.', 'A software driver for the GBA TV Tuner accessory.', 'This utility allows the GBA TV Tuner to scan and display analog signals. While obsolete now, it represents a unique era of GBA hardware expansion and multimedia capabilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gba-tv-tuner-ctrashman', 'GAMEBOYADVANCE', 'GBA TV Tuner (C)(TrashMan)', '2004', 'Hardware', 'Nintendo', '1', 'TV Accessory', 'Utility / Hardware Support.', 'Watch broadcast television on your Game Boy Advance.', 'A software driver for the GBA TV Tuner accessory.', 'The TrashMan release of the TV Tuner software ensures compatibility with specific third-party hardware modules, allowing users to turn their console into a portable television.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gbadev-2004mbit-competition-ugbadevorg', 'GAMEBOYADVANCE', 'GBADev 2004Mbit Competition (U)(GBADev.org)', '2004', 'Development', 'Independent', '1', 'Homebrew Compilation', 'Homebrew / Compilation.', 'Play the best entries from the 2004 homebrew contest.', 'A collection of indie games made for the GBA.', 'This competition cartridge showcases the creativity of the GBA dev community. From tech demos to full mini-games, it’s a piece of history for handheld homebrew enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gegege-no-kitaro-jwrg', 'GAMEBOYADVANCE', 'Gegege no Kitaro (J)(WRG)', '2003', 'Action', 'Rising Star Games', '1', 'Action Adventure', 'Side-scrolling Action Platformer.', 'Fight yokai and stop the spirit world from invading.', 'A stylish action game based on the Gegege no Kitaro anime.', 'Gegege no Kitaro features Kitaro''s iconic powers, like his hair needles and remote-controlled clogs. Explore spooky 2D levels and battle massive bosses from Japanese folklore.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gekido-advance---kintaros-revenge-esquirrels', 'GAMEBOYADVANCE', 'Gekido Advance - Kintaro''s Revenge (E)(Squirrels)', '2002', 'Action', 'NAPS Team', '1', 'Beat ''em Up', '2D Beat ''em Up.', 'Defeat the demon Kintaro and his ninja army.', 'A visually stunning sequel to the PS1 cult classic.', 'Gekido Advance: Kintaro''s Revenge features incredible sprite animation and deep combat. Play as Tetsuo in this high-octane brawler that pushes the GBA''s graphical limits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gekido-advance---kintaros-revenge-uongaku', 'GAMEBOYADVANCE', 'Gekido Advance - Kintaros Revenge (U)(Ongaku)', '2002', 'Action', 'NAPS Team', '1', 'Beat ''em Up', '2D Beat ''em Up.', 'Defeat the demon Kintaro and his ninja army.', 'A visually stunning sequel to the PS1 cult classic.', 'The US version of Gekido Advance delivers intense martial arts action. Master combos, utilize environmental weapons, and experience one of the best soundtracks on the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gekitou-densetsu-noah---dream-management-jrising-sun', 'GAMEBOYADVANCE', 'Gekitou Densetsu Noah - Dream Management (J)(Rising Sun)', '2002', 'Strategy', 'Media Rings', '1', 'Management Simulation', 'Professional wrestling and management.', 'Manage a wrestling stable and win the NOAH championship.', 'A tactical wrestling management sim featuring Mitsuharu Misawa.', 'Gekitou Densetsu Noah focuses on the business and strategy of pro wrestling. Manage training, book matches, and control your wrestlers in the ring to lead the Pro Wrestling NOAH promotion to glory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gekitou!-car-battler-go!-jrapid-fire', 'GAMEBOYADVANCE', 'Gekitou! Car Battler Go! (J)(Rapid Fire)', '2001', 'Action', 'Taito', '2', 'Vehicle Combat', 'Car combat and RPG.', 'Customize your vehicle to win the Car Battler tournament.', 'A unique blend of Mad Max-style combat and RPG exploration.', 'Gekitou! Car Battler Go! features deep vehicle customization. Scavenge for parts in a wasteland and engage in strategic, real-time car battles in this cult-favorite Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gem-smashers-utrashman', 'GAMEBOYADVANCE', 'Gem Smashers (U)(Trashman)', '2003', 'Puzzle', 'Backbone Entertainment', '1', 'Arcade Puzzle', 'Puzzle and Action.', 'Smash all the gems by bouncing off walls and obstacles.', 'A fast-paced puzzle game with a breakout-style twist.', 'Gem Smashers (US) features three unique characters with different physics. Use precision and timing to clear boards of colorful gems across dozens of increasingly difficult levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('genseishin-justirisers---souchaku-chikyuu-no-senshitachi-jcaravan', 'GAMEBOYADVANCE', 'Genseishin Justirisers - Souchaku Chikyuu no Senshitachi (J)(Caravan)', '2004', 'Action', 'Bandai', '1', 'Tokusatsu Action', '2D Side-scrolling Beat ''em up.', 'Protect Earth as a Justiriser hero.', 'A high-energy tokusatsu action game based on the TV series.', 'Justirisers features intense martial arts and special weapon attacks. Choose your favorite hero and battle waves of alien invaders in this polished Japanese brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('genso-maden-saiyuki-jwrg', 'GAMEBOYADVANCE', 'Genso Maden Saiyuki (J)(WRG)', '2001', 'Adventure', 'Koei', '1', 'Story Adventure', 'Tactical RPG.', 'Journey to the West to stop the demon uprising.', 'A strategic RPG based on the popular Saiyuki manga.', 'Genso Maden Saiyuki features grid-based tactical combat and a deep story. Use the unique powers of Sanzo, Goku, Gojyo, and Hakkai to survive the perilous journey to India.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gensou-suikoden-card-stories-jeurasia', 'GAMEBOYADVANCE', 'Gensou Suikoden Card Stories (J)(Eurasia)', '2001', 'Card Game', 'Konami', '1', 'Card RPG', 'Card Battle RPG.', 'Build a deck and relive the stories of the Suikoden world.', 'A strategic card game based on the hit Konami RPG series.', 'Gensou Suikoden Card Stories features beautiful character art and strategic duels. Use iconic heroes and tactical cards to win battles and progress through the Suikoden narrative.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('get-backers---dakkanoku-jagan-fuuin-jcezar', 'GAMEBOYADVANCE', 'Get Backers - Dakkanoku Jagan Fuuin (J)(Cezar)', '2002', 'Action', 'Konami', '1', 'Anime Action', 'Action Adventure.', 'Use the Jagan eye to recover stolen items for clients.', 'A story-driven adventure based on the GetBackers anime.', 'GetBackers: Jagan Fuuin features puzzle-solving and combat. Play as Ban and Ginji, utilizing their unique "Get Back" skills to solve mysteries and fight enemies in the streets of Shinjuku.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('get-backers---jigoku-no-sukaramushu-jeurasia', 'GAMEBOYADVANCE', 'Get Backers - Jigoku no Sukaramushu (J)(Eurasia)', '2003', 'Action', 'Konami', '1', 'Anime Action', '2D Beat ''em up / Action.', 'Battle through hellish levels to complete your recovery mission.', 'A high-octane brawler starring the GetBackers duo.', 'Jigoku no Sukaramushu focuses on fast-paced combat and character-specific moves. Master Ban’s Midou or Ginji’s lightning attacks to clear waves of enemies and bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('get-ride-amdriver---senkou-no-hero-tanjou-jcaravan', 'GAMEBOYADVANCE', 'Get Ride AMDriver - Senkou no Hero Tanjou (J)(Caravan)', '2003', 'Action', 'Konami', '1', 'Racing Action', 'Side-scrolling Action.', 'Use advanced armor "Drivers" to defeat the Bugrom.', 'A high-tech action game based on the AMDriver anime.', 'Get Ride AMDriver features intense combat and a variety of weapon upgrades. Customize your pilot''s gear and engage in fast-paced missions to protect humanity.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('get!-boku-no-mushitsu-jevasion', 'GAMEBOYADVANCE', 'Get! Boku no Mushitsu (J)(Evasion)', '2002', 'Adventure', 'Konami', '1', 'Life Simulation', 'Bug-collecting / Social Sim.', 'Catch, raise, and battle various beetles.', 'A charming Japanese beetle-collecting simulation.', 'Get! Boku no Mushitsu focuses on the joys of nature. Explore forests to find rare beetles, train them, and participate in local tournaments in this relaxing handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('getbackers-dakkanoku---metropolis-dakkan-sakusen-jrising-sun', 'GAMEBOYADVANCE', 'Getbackers Dakkanoku - Metropolis Dakkan Sakusen (J)(Rising Sun)', '2003', 'Action', 'Konami', '1', 'Anime Action', 'Action Adventure.', 'Infiltrate the Metropolis to recover a stolen artifact.', 'A cinematic adventure following the GetBackers team.', 'Metropolis Dakkan Sakusen features stealth elements and strategic combat. Navigate a high-tech city and use your special abilities to outsmart corporate security.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ghost-rider-urising-sun', 'GAMEBOYADVANCE', 'Ghost Rider (U)(Rising Sun)', '2002', 'Action', 'Marvel', '1', 'Beat ''em Up', '2D Side-scrolling Action.', 'Use your hellfire chains to defeat the forces of Mephisto.', 'A gritty action brawler based on the Marvel movie.', 'Ghost Rider (US) features intense combat and high-speed motorcycle levels. Use the Penance Stare and demonic powers to purge the souls of the wicked in this atmospheric action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ghost-trap-jcezar', 'GAMEBOYADVANCE', 'Ghost Trap (J)(Cezar)', '2004', 'Adventure', 'Success', '1', 'Horror Adventure', 'Puzzle / Strategy.', 'Trap ghosts in a grid-based maze.', 'A strategic puzzle game featuring spooky characters.', 'Ghost Trap (Japan) requires quick thinking and spatial logic. Arrange traps to capture wandering spirits and clear levels before you get overwhelmed by the haunting horde.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gli-incredibili-iindependent', 'GAMEBOYADVANCE', 'Gli Incredibili (I)(Independent)', '2004', 'Action', 'Helixe', '1', 'Movie Action', 'Isometric Action / Platformer.', 'Use the Incredibles'' powers to stop Syndrome''s plan.', 'An Italian-localized adventure starring the Pixar family.', 'Gli Incredibili (The Incredibles) features levels tailored to Mr. Incredible, Elastigirl, Dash, and Violet. Switch between heroes to solve puzzles and defeat robotic minions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('glory-days---the-essence-of-war-eendless-piracy', 'GAMEBOYADVANCE', 'Glory Days - The Essence of War (E)(Endless Piracy)', '2002', 'Strategy', 'Sensory Sweep', '4', 'Real-Time Strategy', 'Strategy / Side-scrolling Action.', 'Lead your army in a 2D battlefield using planes and tanks.', 'A unique military strategy game with direct unit control.', 'Glory Days: The Essence of War is an ambitious GBA title. Command paratroopers and heavy artillery while personally piloting a fighter jet to turn the tide of war in real-time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('go!-go!-beckham!-adventure-on-soccer-island-eeurasia', 'GAMEBOYADVANCE', 'Go! Go! Beckham! Adventure On Soccer Island (E)(Eurasia)', '2002', 'Adventure', 'Rage Software', '1', 'Sports Adventure', '2D Platformer / Soccer.', 'Use your soccer skills to save Soccer Island.', 'A wacky platforming adventure starring David Beckham.', 'Go! Go! Beckham! features a unique mechanic where you use a soccer ball to defeat enemies and solve puzzles. It’s a creative blend of sports and traditional platforming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('godzilla-domination-eeurasia', 'GAMEBOYADVANCE', 'Godzilla Domination (E)(Eurasia)', '2002', 'Action', 'Pipeworks', '1', 'Monster Action', '2D Fighting Game.', 'Battle as giant monsters to dominate the city.', 'A high-energy monster brawler featuring Godzilla.', 'Godzilla Domination (Europe) lets you choose from iconic Kaiju like Mothra and King Ghidorah. Smash buildings and flatten your rivals in intense 1-on-1 or multi-monster battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('godzilla-domination-jindependent', 'GAMEBOYADVANCE', 'Godzilla Domination (J)(Independent)', '2002', 'Action', 'Pipeworks', '1', 'Monster Action', '2D Fighting Game.', 'Battle as giant monsters to dominate the city.', 'The original Japanese release of the Kaiju fighter.', 'Experience the giant monster chaos in its Japanese format. Master each monster''s special beams and physical attacks to become the king of the monsters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('godzilla-domination-udumper', 'GAMEBOYADVANCE', 'Godzilla Domination (U)(Dumper)', '2002', 'Action', 'Pipeworks', '1', 'Monster Action', '2D Fighting Game.', 'Battle as giant monsters to dominate the city.', 'The US version of the definitive Godzilla fighter.', 'Godzilla Domination (US) features vibrant sprites and destructible environments. Battle through the story mode or challenge friends to see who is the strongest Kaiju on GBA.');